function sw_index_prepare_protected_preview(string $job): bool
{
    if (!preg_match('/^[a-f0-9]{32}$/i', $job)) {
        return false;
    }
    $jobDir = __DIR__ . DIRECTORY_SEPARATOR . 'engine' . DIRECTORY_SEPARATOR . 'jobs' . DIRECTORY_SEPARATOR . strtolower($job);
    $output = $jobDir . DIRECTORY_SEPARATOR . 'output.wav';
    $protected = $jobDir . DIRECTORY_SEPARATOR . 'protected_full_preview.mp3';
    if (!is_file($output)) {
        return false;
    }
    clearstatcache(true, $protected);
    if (is_file($protected) && (int)@filesize($protected) >= 4096) {
        return true;
    }

    $lock = @fopen($protected . '.lock', 'c+');
    if ($lock === false || !@flock($lock, LOCK_EX)) {
        if (is_resource($lock)) @fclose($lock);
        return false;
    }
    clearstatcache(true, $protected);
    if (!is_file($protected) || (int)@filesize($protected) < 4096) {
        $ffmpeg = is_executable('/usr/bin/ffmpeg') ? '/usr/bin/ffmpeg' : (is_executable('/usr/local/bin/ffmpeg') ? '/usr/local/bin/ffmpeg' : '');
        if ($ffmpeg !== '') {
            $tmp = $protected . '.tmp.' . getmypid();
            @unlink($tmp);
            $filter = "[0:a]aformat=sample_rates=44100:channel_layouts=stereo[main];"
                . "sine=frequency=880:sample_rate=44100,"
                . "volume='if(lt(mod(t,18),0.38),0.075,0)':eval=frame,"
                . "aformat=channel_layouts=stereo[mark];"
                . "[main][mark]amix=inputs=2:duration=first:dropout_transition=0,"
                . "alimiter=limit=0.96[out]";
            $command = escapeshellarg($ffmpeg)
                . ' -hide_banner -loglevel error -nostdin -y'
                . ' -i ' . escapeshellarg($output)
                . ' -filter_complex ' . escapeshellarg($filter)
                . ' -map ' . escapeshellarg('[out]')
                . ' -vn -map_metadata -1 -codec:a libmp3lame -b:a 160k -ar 44100 -ac 2'
                . ' -f mp3 ' . escapeshellarg($tmp) . ' 2>/dev/null';
            $commandOutput = [];
            $exitCode = 1;
            @exec($command, $commandOutput, $exitCode);
            if ($exitCode === 0 && is_file($tmp) && (int)@filesize($tmp) >= 4096) {
                @chmod($tmp, 0664);
                @rename($tmp, $protected);
            }
            @unlink($tmp);
        }
    }
    @flock($lock, LOCK_UN);
    @fclose($lock);
    clearstatcache(true, $protected);
    return is_file($protected) && (int)@filesize($protected) >= 4096;
}

function sw_index_today_bounds(): array
{
    $start = strtotime('today');
    $end = $start !== false ? ($start + 86400) : time();
    return [is_int($start) ? $start : 0, $end];
}

function sw_index_count_jobs_today(): int
{
    [$start, $end] = sw_index_today_bounds();
    $dir = __DIR__ . DIRECTORY_SEPARATOR . 'engine' . DIRECTORY_SEPARATOR . 'jobs';
    if (!is_dir($dir) || !is_readable($dir)) {
        return 0;
    }
    $items = @scandir($dir);
    if (!is_array($items)) {
        return 0;
    }
    $count = 0;
    foreach ($items as $item) {
        if (!preg_match('/^[a-f0-9]{32}$/i', (string)$item)) {
            continue;
        }
        $path = $dir . DIRECTORY_SEPARATOR . $item;
        if (!is_dir($path)) {
            continue;
        }
        $mtime = @filemtime($path);
        if (is_int($mtime) && $mtime >= $start && $mtime < $end) {
            $count++;
        }
    }
    return $count;
}

function sw_index_count_paid_jobs_today(): int
{
    [$start, $end] = sw_index_today_bounds();
    $dir = __DIR__ . DIRECTORY_SEPARATOR . 'engine' . DIRECTORY_SEPARATOR . 'jobs';
    if (!is_dir($dir) || !is_readable($dir)) {
        return 0;
    }
    $items = @scandir($dir);
    if (!is_array($items)) {
        return 0;
    }
    $seen = [];
    foreach ($items as $item) {
        if (!preg_match('/^[a-f0-9]{32}$/i', (string)$item)) {
            continue;
        }
        $paymentPath = $dir . DIRECTORY_SEPARATOR . $item . DIRECTORY_SEPARATOR . 'payment.json';
        if (!is_file($paymentPath) || !is_readable($paymentPath)) {
            continue;
        }
        $raw = (string)@file_get_contents($paymentPath);
        $data = json_decode($raw, true);
        if (!is_array($data)) {
            continue;
        }
        $paid = !empty($data['paid']) || strtolower((string)($data['status'] ?? '')) === 'succeeded';
        if (!$paid) {
            continue;
        }
        $ts = 0;
        foreach (['paid_at', 'captured_at', 'updated_at', 'created_at'] as $key) {
            if (!empty($data[$key])) {
                $parsed = strtotime((string)$data[$key]);
                if ($parsed !== false) {
                    $ts = $parsed;
                    break;
                }
            }
        }
        if (!$ts && isset($data['raw']) && is_array($data['raw'])) {
            foreach (['captured_at', 'created_at'] as $key) {
                if (!empty($data['raw'][$key])) {
                    $parsed = strtotime((string)$data['raw'][$key]);
                    if ($parsed !== false) {
                        $ts = $parsed;
                        break;
                    }
                }
            }
        }
        if ($ts >= $start && $ts < $end) {
            $seen[(string)($data['payment_id'] ?? $item)] = true;
        }
    }
    return count($seen);
}

