function sw_index_count_synthesized_texts_all_time(): int
{
    $root = '/var/lib/sunowave-alt-tts/jobs';
    if (!is_dir($root) || !is_readable($root)) {
        return 0;
    }
    $items = @scandir($root);
    if (!is_array($items)) {
        return 0;
    }
    $count = 0;
    foreach ($items as $item) {
        $jobId = (string)$item;
        if (!preg_match('/^[a-f0-9]{32}$/', $jobId)) {
            continue;
        }
        $jobDir = $root . DIRECTORY_SEPARATOR . $jobId;
        $metaPath = $jobDir . DIRECTORY_SEPARATOR . 'job.json';
        $resultPath = $jobDir . DIRECTORY_SEPARATOR . 'result.wav';
        $metaSize = is_file($metaPath) ? (int)@filesize($metaPath) : 0;
        if ($metaSize < 2 || $metaSize > 200000 || !is_file($resultPath) || (int)@filesize($resultPath) < 44) {
            continue;
        }
        $meta = json_decode((string)@file_get_contents($metaPath), true);
        if (!is_array($meta)) {
            continue;
        }
        if (
            strtolower(trim((string)($meta['task'] ?? ''))) === 'synthesize'
            && strtolower(trim((string)($meta['status'] ?? ''))) === 'done'
        ) {
            $count++;
        }
    }
    return $count;
}

function sw_index_public_stats_cache_path(): string
{
    $runtime = __DIR__ . DIRECTORY_SEPARATOR . 'engine' . DIRECTORY_SEPARATOR . 'runtime';
    if (!is_dir($runtime)) {
        @mkdir($runtime, 0775, true);
    }
    return $runtime . DIRECTORY_SEPARATOR . 'index_public_stats_cache.json';
}

function sw_index_get_cached_public_stats(int $ttlSeconds = 60): array
{
    $cacheVersion = '20260819_synthesized_texts_stats_v1';
    $cachePath = sw_index_public_stats_cache_path();
    $force = isset($_GET['sw_stats_refresh']) && (string)$_GET['sw_stats_refresh'] === '1';
    $uploadedTasksSinceStart = sw_index_count_uploaded_tasks_since_audit_start();
    $cached = null;
    if (is_file($cachePath)) {
        $decoded = json_decode((string)@file_get_contents($cachePath), true);
        if (is_array($decoded)) {
            $cached = $decoded;
        }
    }
    $cacheFresh = is_array($cached)
        && (string)($cached['version'] ?? '') === $cacheVersion
        && (time() - (int)($cached['ts'] ?? 0)) <= $ttlSeconds;
    if (!$force && $cacheFresh) {
        return [
            $uploadedTasksSinceStart,
            (int)($cached['synthesizedTextsAllTime'] ?? 0),
            'journal+cache_hit',
        ];
    }

    $lockPath = $cachePath . '.lock';
    $lock = @fopen($lockPath, 'c+');
    if ($lock && !@flock($lock, LOCK_EX | LOCK_NB)) {
        if (is_array($cached) && (string)($cached['version'] ?? '') === $cacheVersion) {
            @fclose($lock);
            return [$uploadedTasksSinceStart, (int)($cached['synthesizedTextsAllTime'] ?? 0), 'journal+cache_stale_lock'];
        }
        @fclose($lock);
    }

    $jobs = $uploadedTasksSinceStart;
    $synthesizedTexts = sw_index_count_synthesized_texts_all_time();
    $payload = [
        'ts' => time(),
        'created_at' => date('c'),
        'uploadedTasksSinceStart' => $jobs,
        'synthesizedTextsAllTime' => $synthesizedTexts,
        'ttl_seconds' => $ttlSeconds,
        'version' => $cacheVersion,
    ];
    @file_put_contents($cachePath, json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT) . "\n", LOCK_EX);
    @chmod($cachePath, 0664);
    if ($lock) {
        @flock($lock, LOCK_UN);
        @fclose($lock);
    }
    return [(int)$jobs, (int)$synthesizedTexts, 'journal+cache_refresh'];
}

