$clearSavedResultCookies = static function (): void {
    if (PHP_SAPI === 'cli' || headers_sent()) {
        return;
    }
    $expires = time() - 3600;
    $domains = ['', 'suno-wave.ru', '.suno-wave.ru', 'www.suno-wave.ru'];
    $paths = ['/', '/index.php'];
    foreach (['sunowave_last_job', 'sw_last_job'] as $name) {
        foreach ($domains as $domain) {
            foreach ($paths as $path) {
                setcookie($name, '', $expires, $path, $domain, true, true);
            }
        }
    }
};

$saveSavedResultCookie = static function (string $job): void {
    if (PHP_SAPI === 'cli' || headers_sent() || !preg_match('/^[a-f0-9]{32}$/i', $job)) {
        return;
    }
    $expires = time() + 2592000;
    foreach (['sunowave_last_job', 'sw_last_job'] as $name) {
        setcookie($name, strtolower($job), $expires, '/', '', true, false);
    }
};

if ($closeResult) {
    /* codex-result-recall-after-modal-close-v1:
       close the result surface without destroying the saved-result recall
       state. The redirected homepage uses result_closed=1 to avoid opening
       the modal again, while the left recall card can still restore the job. */
    if (PHP_SAPI !== 'cli' && !headers_sent()) {
        header('Location: /?result_closed=1', true, 302);
    }
    exit;
}

$returnJob = $explicitJob;
