    $returnJob = (string)($_COOKIE['sunowave_last_job'] ?? '');
    if (!preg_match('/^[a-f0-9]{32}$/', $returnJob)) {
        $returnJob = (string)($_SESSION['sw_saved_result_job'] ?? '');
    }
}
if ($hasExplicitJob) {
    $returnJob = strtolower($explicitJob);
    $_SESSION['sw_saved_result_job'] = $returnJob;
    $saveSavedResultCookie($returnJob);
} elseif (!$logoutReset && !$resultClosed && preg_match('/^[a-f0-9]{32}$/', $returnJob)) {
    $_SESSION['sw_saved_result_job'] = strtolower($returnJob);
    $saveSavedResultCookie(strtolower($returnJob));
}
if ($logoutReset || $forgetResult) {
    $returnJob = '';
    unset($_SESSION['sw_saved_result_job']);
    $clearSavedResultCookies();
}
if ($resultClosed) {
    $returnJob = '';
}
$hasReturnJob = preg_match('/^[a-f0-9]{32}$/', $returnJob) === 1;
if ($hasReturnJob) {
    sw_index_prepare_protected_preview($returnJob);
}

