function sw_index_inject_body_start_html(string $html, string $module, string $marker): string
{
    if (stripos($html, $marker) !== false) {
        return $html;
    }
    return preg_replace('~(<body\b[^>]*>)~i', '$1' . "\n" . $module, $html, 1) ?? $html;
}

