  const JOB_RE = /^[a-f0-9]{32}$/i;
  const WAVE_FILES = ['input_preview.png', 'source_waveform.png', 'waveform.png', 'before_waveform.png'];

  const now = () => Date.now();
  const isDesktop = () => window.innerWidth >= DESKTOP_MIN;
  const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
  const rect = el => el.getBoundingClientRect();

  function syncResultStages(){
    const source = Array.isArray(window.__swResultOperations37) ? window.__swResultOperations37 : null;
    if (resultStagesImported || !source || source.length !== 37) return resultStagesImported;
    const last = Math.max(1, source.length - 1);
    STAGES.splice(0, STAGES.length, ...source.map((item, index) => ({
      at: index === 0 ? 0 : Math.min(96, Math.round((index / last) * 96)),
      title: index === last ? FINAL_PROCESSING_TITLE : String(item && item[1] || ''),
      text: String(item && item[2] || '')
    })));
    resultStagesImported = true;
    visibleStageIndex = -1;
    lastStageIndex = -1;
    return true;
  }

  function safeStorageGet(store, key) {
    try { return store && store.getItem ? String(store.getItem(key) || '') : ''; } catch (_) { return ''; }
  }

  function readCookieValue(name) {
    try {
      const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const match = document.cookie.match(new RegExp('(?:^|;\\s*)' + escaped + '=([^;]*)'));
      return match ? decodeURIComponent(match[1]) : '';
    } catch (_) {
      return '';
    }
  }

  function readProcessingJobId() {
    const candidates = [];
    try { candidates.push(new URLSearchParams(location.search).get('job') || ''); } catch (_) {}
    candidates.push(
      readCookieValue('sunowave_last_job'),
      readCookieValue('sw_last_job'),
      safeStorageGet(window.localStorage, 'sunowave:last_job'),
      safeStorageGet(window.localStorage, 'sunowave_last_job'),
      safeStorageGet(window.sessionStorage, 'sunowave:last_job'),
      safeStorageGet(window.sessionStorage, 'sunowave_last_job')
    );
    const found = candidates.map(v => String(v || '').trim()).find(v => JOB_RE.test(v));
    return found || '';
  }

  function jobWaveAsset(job, file) {
    return '/engine/jobs/' + encodeURIComponent(job) + '/' + encodeURIComponent(file) + '?swv=' + Math.floor(Date.now() / 2500);
  }

  function isVisible(el) {
    if (!el || el.nodeType !== 1) return false;
    const r = rect(el);
    const cs = getComputedStyle(el);
    return r.width > 2 && r.height > 2 && cs.display !== 'none' && cs.visibility !== 'hidden' && Number(cs.opacity || 1) > 0.02;
  }

  function textOf(el, limit = 700) {
    return String(el && el.textContent ? el.textContent : '').replace(/\s+/g, ' ').trim().slice(0, limit);
  }

  function cleanText(value) {
    return String(value || '')
      .replace(/best\s+ultra\s*[^.\n]*/ig, '')
      .replace(/visual[_\s-]*diff/ig, '')
      .replace(/\bqueued\b|\bqueue\b|\bprocessing\b|\bworker\b|\brender\b|\bspectral\b|\ba\/?b\b/ig, '')
      .replace(/текущий\s+этап\s+воркера\.?/ig, '')
      .replace(/для\s+джуна\s*:?/ig, 'Простыми словами:')
      .replace(/для\s+профи\s*:?/ig, 'То есть:')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function parsePercentFrom(el) {
    if (!el) return 0;
    const style = el.getAttribute('style') || '';
    const aria = el.getAttribute('aria-valuenow') || '';
    const width = /width\s*:\s*([0-9.]+)%/i.exec(style);
    const cssPct = /--sw-process-pct\s*:\s*([0-9.]+)/i.exec(style);
    const textPct = /([0-9]{1,3}(?:[.,][0-9]+)?)\s*%/.exec(textOf(el, 300));
    const n = Number((cssPct && cssPct[1]) || (width && width[1]) || aria || (textPct && textPct[1].replace(',', '.')) || 0);
    return Number.isFinite(n) ? clamp(n, 0, 100) : 0;
  }

  function stageIndexByPercent(percent) {
    const pct = clamp(Number(percent || 0), 0, 100);
    let index = 0;
    for (let i = 0; i < STAGES.length; i++) {
      if (pct >= STAGES[i].at) index = i;
    }
    return index;
  }

  function stageIndexByText(rawTitle, rawDetail) {
    const s = `${rawTitle || ''} ${rawDetail || ''}`.toLowerCase();
    if (/шум|noise|хвост/.test(s)) return 3;
    if (/wave|форма|анализ/.test(s)) return 1;
    if (/пик|clip|перегруз|transient|транзиент/.test(s)) return 2;
    if (/громк|loud|volume|headroom/.test(s)) return 4;
    if (/частот|спектр|eq|баланс|spectral/.test(s)) return 5;
    if (/бас|низ|середин|основа/.test(s)) return 6;
    if (/детал|воздух|панорам|атака/.test(s)) return 7;
    if (/динами|compress|компресс/.test(s)) return 8;
    if (/телефон|науш|систем|перевод/.test(s)) return 9;
    if (/compare|сравн|a\/?b|diff/.test(s)) return 10;
    if (/final|финал|master|мастер|render|рендер/.test(s)) return 11;
    if (/ready|готов|download|скачив/.test(s)) return 12;
    return -1;
  }

  function stableStageIndex(rawTitle, rawDetail, percent) {
    const hasCanonicalStages = syncResultStages();
    if (hasCanonicalStages) {
      const exactIndex = stageIndexByPercent(percent);
      visibleStageIndex = exactIndex;
      lastStageIndex = exactIndex;
      lastSwitchAt = now();
      return exactIndex;
    }
    let target = hasCanonicalStages ? stageIndexByPercent(percent) : stageIndexByText(rawTitle, rawDetail);
    if (target < 0 || TECH_RE.test(`${rawTitle || ''} ${rawDetail || ''}`)) target = stageIndexByPercent(percent);
    target = clamp(target, 0, STAGES.length - 1);
    const t = now();
    if (visibleStageIndex < 0) {
      visibleStageIndex = target;
      lastStageIndex = target;
      lastSwitchAt = t;
      return target;
    }
    if (target !== visibleStageIndex && (t - lastSwitchAt >= STAGE_HOLD_MS || target > visibleStageIndex + 1 || percent >= 96)) {
      visibleStageIndex = target;
      lastStageIndex = target;
      lastSwitchAt = t;
    }
    return visibleStageIndex;
  }

  function findHero() {
    return document.getElementById('swFastDesktopHero') || document.querySelector('.swFastDesktopHero, main[aria-label*="Солнечная"], main, section') || document.body;
  }

  function readCards() {
    const nav = document.querySelector('nav.swFastDesktopCards, .swFastDesktopCards');
    const cards = nav ? Array.from(nav.querySelectorAll('[data-process-card], button, a')) : [];
    cards.forEach(card => {
      const full = textOf(card, 400);
      if (CARD_TEXT_RE.test(full)) card.classList.add('sw-clean-hide-during-processing');
    });
    if (nav) nav.classList.add('sw-clean-hide-during-processing');
    return { nav, cards };
  }

  function readNativeOrb() {
    const orb = document.getElementById('swFastProcessOrb');
    if (!orb) return { active: false, title: '', detail: '', percent: 0 };
    const hidden = orb.getAttribute('aria-hidden') === 'true';
    const title = textOf(orb.querySelector('#swFastProcessTitle, .swFastProcessOrb__copy > b'), 240);
    const detail = textOf(orb.querySelector('#swFastProcessSub, .swFastProcessOrb__copy > span'), 900);
    const percent = parsePercentFrom(orb);
    const combined = `${title} ${detail} ${textOf(orb, 1200)}`;
    const active = percent > 1 || (armed && !hidden && PROCESS_RE.test(combined));
    return { active, title, detail, percent };
  }

  function readFastStatus() {
    const status = document.getElementById('swFastStatus') || document.querySelector('.swFastStatus');
    if (!status) return { active: false, title: '', detail: '', percent: 0, elements: [] };
    status.classList.add('sw-processing-duplicate-status');
    const bar = status.querySelector('#swFastStatusBar');
    const percent = parsePercentFrom(bar || status);
    const title = textOf(status.querySelector('#swFastStatusTitle') || status.querySelector('b'), 240);
    const detail = textOf(status.querySelector('#swFastStatusText') || status.querySelector('span'), 900);
    const combined = `${title} ${detail}`;
    const active = percent > 1 || (armed && PROCESS_RE.test(combined));
    return { active, title, detail, percent, elements: [status] };
  }

  function ensureOrb(hero) {
    syncResultStages();
    let orb = document.getElementById('swFastProcessOrb');
    if (!orb) {
      orb = document.createElement('section');
      orb.id = 'swFastProcessOrb';
      orb.className = 'swFastProcessOrb sw-clean-processing-orb';
      orb.setAttribute('aria-live', 'polite');
      orb.setAttribute('aria-hidden', 'false');
      orb.innerHTML = '<div class="swFastProcessOrb__rings sw-clean-processing-orb__rings" aria-hidden="true"></div><canvas id="swFastWaveCanvas" width="520" height="220"></canvas><div class="swFastProcessOrb__copy"><b id="swFastProcessTitle">Музыкальный мастеринг</b><span id="swFastProcessSub">Готовим аудио к обработке.</span></div>';
    }
    orb.querySelectorAll('.swFastProcessOrb__sun, .sw-clean-processing-orb__sun').forEach(el => el.remove());
    orb.classList.add('sw-orb-final-polish');
    orb.setAttribute('aria-hidden', 'false');
    if (orb.parentElement !== hero) hero.appendChild(orb);

    let finalCopy = orb.querySelector('.swFinalOrbCopy');
    if (!finalCopy) {
      finalCopy = document.createElement('div');
      finalCopy.className = 'swFinalOrbCopy';
      finalCopy.setAttribute('aria-live', 'polite');
      finalCopy.innerHTML = '<span class="swFinalOrbCopy__wait">Пожалуйста, подождите немного</span><b class="swFinalOrbCopy__title"></b><span class="swFinalOrbCopy__text"></span><span class="swFinalOrbCopy__steps" aria-hidden="true"></span>';
      orb.appendChild(finalCopy);
    }
    finalCopy.querySelectorAll('.swFinalOrbCopy__stageCounter, [data-sw-best-counter], .swBestStageCounter, .swFinalOrbCopy__eta').forEach((el) => el.remove());
    const steps = finalCopy.querySelector('.swFinalOrbCopy__steps');
    if (steps && steps.children.length !== STAGES.length) {
      steps.innerHTML = STAGES.map(() => '<i></i>').join('');
    }
    return orb;
  }

  function setOrbContent(orb, rawTitle, rawDetail, percent) {
    syncResultStages();
    const stageIndex = stableStageIndex(rawTitle, rawDetail, percent);
    const stage = STAGES[stageIndex] || STAGES[0];
    const pageState = String(document.body && document.body.dataset && document.body.dataset.pageState || '').toLowerCase();
    const displayStage = pageState === 'uploading'
      ? { title: 'Приемка файла', text: 'Идет приемка файла и рендеринг графической волны.' }
      : stage;
    const copy = orb.querySelector('.swFinalOrbCopy');
    if (!copy) return;
    const titleEl = copy.querySelector('.swFinalOrbCopy__title');
    const textEl = copy.querySelector('.swFinalOrbCopy__text');
    const counterEl = copy.querySelector('[data-sw-best-counter]');
    const stepsRoot = copy.querySelector('.swFinalOrbCopy__steps');
    if (stepsRoot && stepsRoot.children.length !== STAGES.length) {
      stepsRoot.innerHTML = STAGES.map(() => '<i></i>').join('');
    }
    const steps = Array.from(copy.querySelectorAll('.swFinalOrbCopy__steps i'));

    if (copy.dataset.stageIndex !== String(stageIndex)) {
      copy.classList.add('is-switching');
      window.setTimeout(() => copy.classList.remove('is-switching'), 180);
      copy.dataset.stageIndex = String(stageIndex);
    }
    if (titleEl && titleEl.textContent !== displayStage.title) titleEl.textContent = displayStage.title;
    if (textEl && textEl.textContent !== displayStage.text) textEl.textContent = displayStage.text;
    if (counterEl) counterEl.textContent = 'Этап ' + (stageIndex + 1) + ' из ' + STAGES.length;
    steps.forEach((dot, i) => dot.classList.toggle('is-on', i <= stageIndex));

    const safePct = percent > 0 ? percent : Math.max(2, STAGES[stageIndex].at);
    orb.style.setProperty('--sw-process-pct', clamp(safePct, 0, 100).toFixed(2));
    window.__swProcessingStage37 = { index: stageIndex, total: STAGES.length, title: displayStage.title, text: displayStage.text, percent: safePct };
  }

  function ensureProcessingTrust() {
    const copy = document.querySelector('.swFastDesktopCopy');
    if (copy) {
      copy.classList.add('sw-processing-duplicate-status');
    }
    document.querySelectorAll('.swProcessingTrust,.swIndexProofMetrics').forEach(el => {
      el.classList.add('sw-processing-duplicate-status');
    });
    return null;
  }

  function ensureProcessingTimer(hero) {
    let timer = document.getElementById('swProcessingTimer');
    if (!timer) {
      timer = document.createElement('div');
      timer.id = 'swProcessingTimer';
      timer.className = 'swProcessingTimer';
      timer.setAttribute('role', 'timer');
      timer.setAttribute('aria-live', 'off');
      timer.innerHTML = '<span class="swProcessingTimer__label">Пламя работает</span><b class="swProcessingTimer__digits">000</b><small class="swProcessingTimer__unit">сек</small>';
    }
    if (timer.parentElement !== hero) hero.appendChild(timer);
    timer.style.setProperty('display', 'none', 'important');
    timer.style.setProperty('visibility', 'hidden', 'important');
    timer.style.setProperty('opacity', '0', 'important');
    timer.style.setProperty('pointer-events', 'none', 'important');
    return null;
  }

  function hardenProcessingVisuals(hero, orb) {
    if (orb) {
      orb.querySelectorAll('.swFastProcessOrb__copy:not(.swFinalOrbCopy), #swFastProcessTitle, #swFastProcessSub').forEach(el => {
        el.classList.add('sw-processing-duplicate-status');
        el.style.setProperty('display', 'none', 'important');
        el.style.setProperty('visibility', 'hidden', 'important');
        el.style.setProperty('opacity', '0', 'important');
        el.style.setProperty('pointer-events', 'none', 'important');
      });
      const timer = orb.querySelector('#swProcessingTimer');
      if (timer) {
        timer.style.setProperty('display', 'none', 'important');
        timer.style.setProperty('visibility', 'hidden', 'important');
        timer.style.setProperty('opacity', '0', 'important');
      }
    }

    document.querySelectorAll('nav.swFastDesktopCards, .swFastDesktopCards, .swFastDesktopCard, [data-process-card]').forEach(el => {
      el.classList.add('sw-processing-duplicate-status');
      el.style.setProperty('display', 'none', 'important');
      el.style.setProperty('visibility', 'hidden', 'important');
      el.style.setProperty('opacity', '0', 'important');
      el.style.setProperty('pointer-events', 'none', 'important');
    });

    Array.from((hero || document).querySelectorAll('article, section, div, a, button'))
      .filter(el => !el.closest('#swFastProcessOrb'))
      .filter(el => !el.closest('.swFastDesktopCopy, .swProcessingTrust'))
      .filter(el => /Анализ трека|Считываем реальную|waveform|пики|шумовой хвост|BEST ULTRA|SPECTRAL|REPAIR PRO/i.test(textOf(el, 260)))
      .forEach(el => {
        const r = rect(el);
        if (r.width >= 120 && r.height >= 40 && r.height <= 420) {
          el.classList.add('sw-processing-duplicate-status');
          el.style.setProperty('display', 'none', 'important');
          el.style.setProperty('visibility', 'hidden', 'important');
          el.style.setProperty('opacity', '0', 'important');
          el.style.setProperty('pointer-events', 'none', 'important');
        }
      });

    Array.from((hero || document).querySelectorAll('article, section, div, a, button'))
      .filter(el => !el.closest('#swFastProcessOrb'))
      .filter(el => !el.closest('.swFastDesktopCopy, .swProcessingTrust'))
      .filter(el => /Анализ трека|Считываем реальную|реальную waveform|шумовой хвост|BEST ULTRA|SPECTRAL|REPAIR PRO|visual[_\s-]*diff|текущий этап воркера/i.test(textOf(el, 320)))
      .forEach(el => {
        const r = rect(el);
        if (r.width >= 120 && r.height >= 40 && r.height <= 460) {
          el.classList.add('sw-processing-duplicate-status');
          el.style.setProperty('display', 'none', 'important');
          el.style.setProperty('visibility', 'hidden', 'important');
          el.style.setProperty('opacity', '0', 'important');
          el.style.setProperty('pointer-events', 'none', 'important');
        }
      });
  }

  function ensureProcessingWave(orb) {
    if (!orb) return null;
    let wrap = orb.querySelector('.swProcessingWaveBurst');
    if (!wrap) {
      wrap = document.createElement('div');
      wrap.className = 'swProcessingWaveBurst';
      wrap.setAttribute('aria-hidden', 'true');
      wrap.innerHTML = '<img alt="">';
      orb.appendChild(wrap);
    }
    const img = wrap.querySelector('img');
    const job = readProcessingJobId();
    if (!img || !job) {
      wrap.classList.add('is-empty');
      return wrap;
    }
    if (wrap.dataset.job === job && !wrap.classList.contains('is-empty')) return wrap;
    if (wrap.dataset.job === job && Number(wrap.dataset.nextRetry || 0) > now()) return wrap;
    wrap.dataset.job = job;
    wrap.dataset.waveIndex = '0';
    wrap.classList.add('is-empty');

    const loadCandidate = () => {
      const index = Number(wrap.dataset.waveIndex || 0);
      if (index >= WAVE_FILES.length) {
        wrap.classList.add('is-empty');
        wrap.dataset.nextRetry = String(now() + 3200);
        return;
      }
      img.src = jobWaveAsset(job, WAVE_FILES[index]);
    };

    img.onload = () => { wrap.classList.remove('is-empty'); };
    img.onerror = () => {
      wrap.dataset.waveIndex = String(Number(wrap.dataset.waveIndex || 0) + 1);
      loadCandidate();
    };
    loadCandidate();
    return wrap;
  }

  function updateProcessingTimer(timer) {
    if (!timer) return;
    if (!processingStartedAt) processingStartedAt = now();
    const seconds = Math.max(0, Math.floor((now() - processingStartedAt) / 1000));
    const digits = timer.querySelector('.swProcessingTimer__digits');
    if (!digits || digits.dataset.seconds === String(seconds)) return;
    digits.dataset.seconds = String(seconds);
    digits.textContent = String(seconds).padStart(3, '0');
    digits.classList.remove('is-ticking');
    void digits.offsetWidth;
    digits.classList.add('is-ticking');
    timer.setAttribute('aria-label', 'Обработка идет ' + seconds + ' секунд');
  }

  function layoutOrb(hero, orb) {
    // Обработчик держим в правой зоне viewport, чтобы он не залезал на логотип, заголовок и кнопку.
    // Это убирает зависимость от внутренних сеток fast-shell и стабилизирует визуал.
    if (hero && getComputedStyle(hero).position === 'static') hero.style.position = 'relative';

    const vw = Math.max(981, window.innerWidth || document.documentElement.clientWidth || 981);
    const vh = Math.max(620, window.innerHeight || document.documentElement.clientHeight || 620);
    const copy = document.querySelector('.swFastDesktopCopy');
    const copyBox = copy && isVisible(copy) ? rect(copy) : null;
    const copyVisible = !!copyBox;
    const copyRight = clamp(copyBox ? copyBox.right : vw * 0.18, 180, vw * 0.36);
    const gap = clamp(vw * 0.035, 48, 72);
    const rightPad = clamp(vw * 0.025, 28, 52);
    const timerReserve = copyVisible ? clamp(vw * 0.145, 145, 286) : clamp(vw * 0.07, 64, 138);
    const availableWidth = Math.max(360, vw - copyRight - gap - rightPad - timerReserve);
    const diameter = Math.round(clamp(Math.min(vw * 0.42, vh * 0.82, availableWidth), 400, 720));
    const radius = diameter / 2;

    const leftSafe = copyRight + gap + radius;
    const rightSafe = vw - rightPad - timerReserve - radius;
    const topSafe = radius + 18;
    const bottomSafe = vh - radius - 22;
    const preferredX = copyVisible ? vw * 0.725 : vw * 0.58;
    const targetX = leftSafe <= rightSafe ? clamp(preferredX, leftSafe, rightSafe) : rightSafe;
    const targetY = clamp(vh * 0.505, topSafe, bottomSafe);

    const root = document.documentElement;
    const left = Math.round(targetX) + 'px';
    const top = Math.round(targetY) + 'px';
    const size = diameter + 'px';

    if (root.style.getPropertyValue('--sw-final-orb-center-x') !== left) root.style.setProperty('--sw-final-orb-center-x', left);
    if (root.style.getPropertyValue('--sw-final-orb-center-y') !== top) root.style.setProperty('--sw-final-orb-center-y', top);
    if (root.style.getPropertyValue('--sw-final-orb-size') !== size) root.style.setProperty('--sw-final-orb-size', size);
    root.style.setProperty('--sw-final-orb-left', Math.round(targetX - radius) + 'px');
    const timerLeft = Math.round(targetX + radius + clamp(vw * .012, 12, 24));
    root.style.setProperty('--sw-final-timer-left', timerLeft + 'px');
    root.style.setProperty('--sw-final-timer-width', Math.max(96, Math.round(vw - rightPad - timerLeft)) + 'px');
  }

  function hideDuplicateProcessingBlocks(hero) {
    readCards();
    const selector = '#swFastStatus, .swFastStatus';
    document.querySelectorAll(selector).forEach(el => el.classList.add('sw-processing-duplicate-status'));
    Array.from((hero || document).querySelectorAll('*'))
      .filter(el => !el.closest('#swFastProcessOrb'))
      .filter(el => !el.closest('nav.swFastDesktopCards, .swFastDesktopCards'))
      .filter(el => !el.closest('.swFastDesktopCopy, .swProcessingTrust'))
      .filter(isVisible)
      .filter(el => PROCESS_RE.test(textOf(el, 600)))
      .forEach(el => {
        const r = rect(el);
        if (r.width >= 160 && r.height >= 24 && r.height <= 230) el.classList.add('sw-processing-duplicate-status');
      });
  }

  function stopProcessingLoop(root) {
    if (guardTimer) {
      window.clearInterval(guardTimer);
      guardTimer = 0;
    }
    if (raf) {
      window.cancelAnimationFrame(raf);
      raf = 0;
    }
    armed = false;
    processingStartedAt = 0;
    if (root.classList.contains('sw-processing-final-active')) root.classList.remove('sw-processing-final-active');
  }

  function update() {
    const root = document.documentElement;
    if (!isDesktop()) {
      stopProcessingLoop(root);
      return;
    }

    const native = readNativeOrb();
    const fast = readFastStatus();
    const pageState = String(document.body && document.body.dataset ? (document.body.dataset.pageState || '') : '');
    const stateActive = root.classList.contains('upload-active') || /^(uploading|processing|queued|paid-processing)$/i.test(pageState);
    const active = native.active || fast.active || stateActive;
    if (!active) {
      stopProcessingLoop(root);
      return;
    }

    const hero = findHero();
    const orb = ensureOrb(hero);
    const source = native.active ? native : fast;
    const percent = source.percent || native.percent || fast.percent || parsePercentFrom(orb) || 2;

    if (!root.classList.contains('sw-processing-final-active')) root.classList.add('sw-processing-final-active');
    ensureProcessingTrust();
    const secondsTimer = ensureProcessingTimer(orb);
    updateProcessingTimer(secondsTimer);
    ensureProcessingWave(orb);
    setOrbContent(orb, source.title, source.detail, percent);
    hardenProcessingVisuals(hero, orb);
    layoutOrb(hero, orb);
    hideDuplicateProcessingBlocks(hero);

    if (!guardTimer) {
      guardTimer = window.setInterval(() => {
        const stateNow = String(document.body && document.body.dataset ? (document.body.dataset.pageState || '') : '');
        const stillActive = document.documentElement.classList.contains('sw-processing-final-active')
          || document.documentElement.classList.contains('upload-active')
          || /^(uploading|processing|queued|paid-processing)$/i.test(stateNow);
        if (!stillActive) {
          stopProcessingLoop(document.documentElement);
          return;
        }
        const heroNow = findHero();
        const orbNow = document.getElementById('swFastProcessOrb');
        if (!orbNow) return;
        const nativeNow = readNativeOrb();
        const fastNow = readFastStatus();
        const sourceNow = nativeNow.active ? nativeNow : fastNow;
        setOrbContent(orbNow, sourceNow.title, sourceNow.detail, sourceNow.percent || parsePercentFrom(orbNow) || 2);
        ensureProcessingTrust();
        updateProcessingTimer(ensureProcessingTimer(orbNow));
        ensureProcessingWave(orbNow);
        hardenProcessingVisuals(heroNow, orbNow);
        layoutOrb(heroNow, orbNow);
        hideDuplicateProcessingBlocks(heroNow);
      }, 220);
    }
  }

  function schedule() {
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(update);
  }

  document.addEventListener('click', event => {
    if (event.target && event.target.closest && event.target.closest('[data-upload-trigger]')) {
      armed = true;
      schedule();
    }
  }, true);

  document.addEventListener('change', event => {
    const target = event.target;
    if (target && target.matches && target.matches('input[type="file"]')) {
      armed = true;
      processingStartedAt = now();
      schedule();
    }
  }, true);

  document.addEventListener('DOMContentLoaded', schedule, { once: true });
  window.addEventListener('load', schedule, { once: true });
  window.addEventListener('resize', schedule, { passive: true });

  const observer = new MutationObserver(schedule);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['class']
  });
  if (document.body) {
    observer.observe(document.body, {
      attributes: true,
      attributeFilter: ['data-page-state']
    });
  }
})();
</script>
