<script id="codex-explain-image-button-v1-js">
(() => {
  'use strict';
  if (window.__swExplainImageButtonV1) return;
  window.__swExplainImageButtonV1 = true;

  const sync = () => {
    const root = document.documentElement;
    const cloud = document.querySelector('.swFastDesktopCopy > .swExplainCloud');
    if (!cloud) return;
    const desktop = window.matchMedia && window.matchMedia('(min-width:1024px)').matches;
    const normalHome = !root.classList.contains('swSaveData')
      && !root.classList.contains('upload-active')
      && !root.classList.contains('sw-has-result-recall');
    if (!desktop || !normalHome) {
      cloud.style.removeProperty('--sw-explain-image-left');
      cloud.style.removeProperty('--sw-explain-image-top');
      return;
    }

    const heading = document.querySelector('.swFastDesktopCopy > h1');
    const metrics = document.querySelector('.swIndexProofMetrics');
    if (!heading || !metrics) return;
    const headingRect = heading.getBoundingClientRect();
    const metricsRect = metrics.getBoundingClientRect();
    const cloudRect = cloud.getBoundingClientRect();
    if (headingRect.height < 60 || metricsRect.width < 240 || metricsRect.height < 60 || cloudRect.width < 120) return;

    const headingStyle = window.getComputedStyle(heading);
    const lineHeight = parseFloat(headingStyle.lineHeight) || (headingRect.height / 3);
    const secondLineCenter = headingRect.top + (lineHeight * 1.5);
    const metricsTransform = window.getComputedStyle(metrics).transform;
    const transformParts = metricsTransform && metricsTransform !== 'none'
      ? metricsTransform.replace(/^matrix3d?\(|\)$/g, '').split(',').map(Number)
      : [];
    const proofShiftY = transformParts.length === 16
      ? (transformParts[13] || 0)
      : (transformParts.length === 6 ? (transformParts[5] || 0) : 0);
    const metricsDesignTop = metricsRect.top - proofShiftY;
    const targetCenterY = secondLineCenter + ((metricsDesignTop - secondLineCenter) / 2);
    const left = metricsRect.right - cloudRect.width;
    const unclampedTop = targetCenterY - (cloudRect.height / 2) + (cloudRect.height * 0.15);
    const top = Math.max(90, Math.min(window.innerHeight - cloudRect.height - 54, unclampedTop));

    cloud.style.setProperty('--sw-explain-image-left', left.toFixed(3) + 'px');
    cloud.style.setProperty('--sw-explain-image-top', top.toFixed(3) + 'px');
  };

  let frame = 0;
  const schedule = () => {
    if (frame) return;
    frame = window.requestAnimationFrame(() => {
      frame = 0;
      sync();
    });
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', schedule, { once:true });
  else schedule();
  window.addEventListener('resize', schedule, { passive:true });
  window.addEventListener('orientationchange', schedule, { passive:true });
  new MutationObserver(schedule).observe(document.documentElement, { attributes:true, attributeFilter:['class'] });
})();
</script>
<script type="module" id="sw-index-solar-minusa-override-v1-js">
  (() => {
    const stage = document.getElementById('swIndexWebglSun');
    if (!stage || stage.dataset.swIndexSolarOverride === '1') return;
    stage.dataset.swIndexSolarOverride = '1';
    stage.__swIndexSunDisposed = true;
    document.documentElement.classList.add('swIndexSolarMinusa');
    document.documentElement.classList.add('swIndexSolarDeferred');
    stage.setAttribute('data-sw-planet-state', 'deferred');
    stage.setAttribute('data-sw-sun-interaction-shield', '1');
    ['data-sdo-hmi','data-sdo-aia304','data-sdo-aia171','data-sdo-aia193'].forEach((attr) => stage.removeAttribute(attr));

    const INTERACTION_SHIELD_MS = 1200;
    let sunInteractiveAt = performance.now() + INTERACTION_SHIELD_MS;
    let sunApi = null;
    let mountQueued = false;
    let mountPromise = null;
    let mountEpoch = 0;
    let loadObservers = [];
    let idleSunRequested = false;
    const processingSunButton = document.getElementById('swIndexRealSunReveal');
    const idleSunButton = document.createElement('button');
    idleSunButton.type = 'button';
    idleSunButton.className = 'swIndexRealSunOptIn';
    idleSunButton.textContent = 'Показать настоящее солнце';
    idleSunButton.setAttribute('aria-controls', 'swIndexWebglSun');
    idleSunButton.setAttribute('aria-pressed', 'false');
    idleSunButton.setAttribute('aria-label', 'Загрузить интерактивное настоящее солнце вместо облегчённой заглушки');
    document.body.appendChild(idleSunButton);
    const processingStarted = () => {
      const state = String(document.body && document.body.dataset ? document.body.dataset.pageState : '');
      return document.documentElement.classList.contains('upload-active')
        || document.documentElement.classList.contains('sw-processing-final-active')
        || /^(uploading|processing|queued|paid-processing)$/i.test(state);
    };
    const sceneRequested = () => idleSunRequested;
    window.setTimeout(() => {
      stage.removeAttribute('data-sw-sun-interaction-shield');
    }, INTERACTION_SHIELD_MS);

    const syncOfferLine = () => {
      const offer = document.querySelector('.swFastLegalConsent');
      const orb = document.getElementById('swFastProcessOrb');
      if (!offer) return;
      if (!window.matchMedia || !window.matchMedia('(min-width:1024px)').matches) {
        offer.style.removeProperty('--sw-offer-left');
        offer.style.removeProperty('--sw-offer-top');
        offer.style.removeProperty('--sw-offer-width');
        return;
      }
      const visibleAnchor = (selector) => {
        const el = document.querySelector(selector);
        if (!el) return null;
        const style = window.getComputedStyle(el);
        const r = el.getBoundingClientRect();
        if (style.display === 'none' || style.visibility === 'hidden' || r.width < 120 || r.height < 20) return null;
        return { el, r };
      };
      const anchor = visibleAnchor('.swIndexProofMetrics')
        || visibleAnchor('nav.swFastDesktopCards, .swFastDesktopCards')
        || (orb ? { el: orb, r: orb.getBoundingClientRect() } : null);
      if (!anchor) return;
      const r = anchor.r;
      const isCardAnchor = anchor.el && (anchor.el.matches('.swIndexProofMetrics') || anchor.el.matches('nav.swFastDesktopCards, .swFastDesktopCards'));
      if (!r || r.width < 120 || (!isCardAnchor && r.height < 120)) return;
      const width = isCardAnchor ? r.width : Math.min(720, Math.max(560, r.width + 190));
      const left = isCardAnchor
        ? Math.max(24, Math.min(window.innerWidth - width - 24, r.left))
        : Math.max(24, Math.min(window.innerWidth - width - 24, r.left + (r.width - width) / 2));
      const top = Math.max(92, Math.min(window.innerHeight - 52, r.bottom + (isCardAnchor ? 10 : 18)));
      offer.style.setProperty('--sw-offer-left', `${Math.round(left)}px`);
      offer.style.setProperty('--sw-offer-top', `${Math.round(top)}px`);
      offer.style.setProperty('--sw-offer-width', `${Math.round(width)}px`);
    };

    let offerFrame = 0;
    const scheduleOfferSync = () => {
      if (offerFrame) return;
      offerFrame = window.requestAnimationFrame(() => {
        offerFrame = 0;
        syncOfferLine();
      });
    };

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', scheduleOfferSync, { once:true });
    else scheduleOfferSync();
    window.addEventListener('resize', scheduleOfferSync, { passive:true });
    window.addEventListener('orientationchange', scheduleOfferSync, { passive:true });

    const canMountWebgl = () => {
      if (!sceneRequested()) return false;
      if (document.visibilityState && document.visibilityState !== 'visible') return false;
      if (!idleSunRequested && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return false;
      return true;
    };

    let lastProcessingState = null;
    const syncDeferredState = (force = false) => {
      const active = sceneRequested();
      const stateChanged = lastProcessingState === null || lastProcessingState !== active;
      lastProcessingState = active;
      if (stateChanged || force) {
        const deferred = !active;
        if (document.documentElement.classList.contains('swIndexSolarDeferred') !== deferred) {
          document.documentElement.classList.toggle('swIndexSolarDeferred', deferred);
        }
      }
      if (!active) {
        if (!stateChanged && !force) return false;
        mountEpoch += 1;
        disposeSun();
        stage.setAttribute('data-sw-planet-state', 'deferred');
        stage.classList.remove('is-sun-frame-visible', 'is-three-ready');
        document.documentElement.classList.remove('swIndexSolarSunReady', 'swSunLoading');
      }
      return active;
    };

    const cursorClass = 'swIndexSunCursorActive';
    const cursorDragClass = 'swIndexSunCursorDragging';
