<script id="swCrystalRemakeEntryV1Js">
  (function(){
    function addCrystalEntry(){
      return;
      if(document.getElementById('swCrystalRemakeEntry')) return;
      var host=document.querySelector('.swFastDesktopCopy')||document.querySelector('.swFastLiteMobile')||document.querySelector('main')||document.body;
      var card=document.createElement('a');
      card.id='swCrystalRemakeEntry';
      card.className='swCrystalRemakeEntry';
      card.href='/master.php?crystal=1';
      card.innerHTML='<strong><b>Кристальный ремейк минуса</b><span>Без нового вокала. Сохраняем ритм, ноты и структуру исходника, усиливаем чистоту, плотность, ширину и студийный блеск.</span></strong><em>450 ₽</em>';
      var after=host.querySelector('.swResultRecall')||host.querySelector('.swFastDesktopCta')||host.querySelector('.swFastDesktopLead')||host.lastElementChild;
      if(after&&after.parentNode) after.insertAdjacentElement('afterend',card); else host.appendChild(card);
    }
    if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',addCrystalEntry); else addCrystalEntry();
  })();
</script>
