    $sunProcessingMotionModule = <<<'HTML'
<style id="sw-index-sun-processing-motion-v1">
  html:not(.swSaveData).sw-processing-final-active .swIndexWebglSun,
  html:not(.swSaveData).upload-active .swIndexWebglSun,
  body[data-page-state="uploading"] .swIndexWebglSun,
  body[data-page-state="processing"] .swIndexWebglSun,
  body[data-page-state="queued"] .swIndexWebglSun,
  body[data-page-state="paid-processing"] .swIndexWebglSun,
  html:not(.swSaveData) .swIndexWebglSun[data-sw-sun-process-motion="settling"]{
    transform:translate3d(0,0,0) scale(var(--sw-sun-process-scale,1)) rotate(var(--sw-sun-process-rotation,0deg))!important;
    transform-origin:50% 50%!important;
    will-change:transform!important;
    backface-visibility:hidden!important;
  }

</style>
<script id="sw-index-sun-processing-motion-v1-js">
  (function(){
    var stage = document.getElementById('swIndexWebglSun');
    if (!stage || stage.dataset.swSunProcessingMotion === '1') return;
    stage.dataset.swSunProcessingMotion = '1';

    var docEl = document.documentElement;
    var rafId = 0;
    var pollId = 0;
    var currentScale = 1;
    var rotation = 0;
    var lastFrameAt = 0;
    var activeStartedAt = 0;
    var lastObservedPercent = 0;

    function clamp(value, min, max) {
      value = Number(value);
      if (!Number.isFinite(value)) return min;
      return Math.max(min, Math.min(max, value));
    }

    function activeState() {
      var state = String(document.body && document.body.dataset ? document.body.dataset.pageState || '' : '');
      return docEl.classList.contains('upload-active')
        || docEl.classList.contains('sw-processing-final-active')
        || /^(uploading|processing|queued|paid-processing)$/i.test(state);
    }

    function parsePercentFrom(el) {
      if (!el) return 0;
      var inline = el.getAttribute('style') || '';
      var aria = el.getAttribute('aria-valuenow') || '';
      var width = /width\s*:\s*([0-9.]+)%/i.exec(inline);
      var cssPct = /--sw-process-pct\s*:\s*([0-9.]+)/i.exec(inline);
      var text = String(el.textContent || '').slice(0, 900);
      var textPct = /([0-9]{1,3}(?:[.,][0-9]+)?)\s*%/.exec(text);
      var value = (cssPct && cssPct[1]) || (width && width[1]) || aria || (textPct && textPct[1].replace(',', '.')) || 0;
      return clamp(value, 0, 100);
    }

    function readPercent() {
      var selectors = [
        '#swFastProcessOrb',
        '#swFastStatusBar',
        '#swFastStatus',
        '.swFastStatus',
        '.swFastProcessOrb--mobile',
        '[aria-valuenow]'
      ];
      var percent = 0;
      selectors.forEach(function(selector){
        document.querySelectorAll(selector).forEach(function(el){
          percent = Math.max(percent, parsePercentFrom(el));
        });
      });
      if (percent > 0) lastObservedPercent = percent;
      return percent || lastObservedPercent || 0;
    }

    function fallbackPercent(now) {
      if (!activeStartedAt) activeStartedAt = now;
      var elapsed = Math.max(0, now - activeStartedAt);
      return clamp(5 + 88 * (1 - Math.exp(-elapsed / 90000)), 5, 96);
    }

    function exponentialProgress(percent) {
      var p = clamp(percent / 100, 0, 1);
      return (Math.exp(3 * p) - 1) / (Math.exp(3) - 1);
    }

    function cleanupIfIdle() {
      if (Math.abs(currentScale - 1) > 0.002) return false;
      currentScale = 1;
      stage.style.removeProperty('--sw-sun-process-scale');
      stage.style.removeProperty('--sw-sun-process-rotation');
      stage.removeAttribute('data-sw-sun-process-motion');
      activeStartedAt = 0;
      lastObservedPercent = 0;
      return true;
    }

    function frame(now) {
      rafId = 0;
      if (!lastFrameAt) lastFrameAt = now;
      var dt = clamp((now - lastFrameAt) / 1000, 0, 0.08);
      lastFrameAt = now;

      var active = activeState();
      if (active && !activeStartedAt) activeStartedAt = now;

      var percent = active ? readPercent() : 0;
      if (active && percent <= 0) percent = fallbackPercent(now);
      var expo = active ? exponentialProgress(percent) : 0;
      var targetScale = active ? 1 + 0.5 * expo : 1;
      var spinDuration = 34 - 18 * expo;
      currentScale += (targetScale - currentScale) * (active ? 0.085 : 0.11);

      if (active) {
        rotation = (rotation + dt * (360 / spinDuration)) % 360;
        stage.setAttribute('data-sw-sun-process-motion', 'active');
      } else if (currentScale > 1.002) {
        stage.setAttribute('data-sw-sun-process-motion', 'settling');
      }

      stage.style.setProperty('--sw-sun-process-scale', currentScale.toFixed(4));
      stage.style.setProperty('--sw-sun-process-rotation', rotation.toFixed(2) + 'deg');

      if (active || !cleanupIfIdle()) requestTick();
    }

    function requestTick() {
      if (!rafId) rafId = window.requestAnimationFrame(frame);
    }

    function sync() {
      if (activeState() || stage.getAttribute('data-sw-sun-process-motion')) requestTick();
    }

    var htmlObserver = new MutationObserver(sync);
    htmlObserver.observe(docEl, { attributes:true, attributeFilter:['class'] });
    if (document.body) {
      new MutationObserver(sync).observe(document.body, { attributes:true, attributeFilter:['data-page-state'] });
    }
    window.addEventListener('pagehide', function(){
      if (rafId) window.cancelAnimationFrame(rafId);
      if (pollId) window.clearInterval(pollId);
    }, { once:true });
    sync();
  })();
</script>
