<script id="sw-index-processing-25-stages-v1-js">
  (function(){
    if (window.__swIndexProcessing25StagesV1) return;
    window.__swIndexProcessing25StagesV1 = true;
    var FINAL_PROCESSING_TITLE = 'Сравниваем 7 вариантов и выпускаем лучший';

    var STAGES = [
      { at:0, title:'Приемка файла', text:'Идет приемка файла и рендеринг графической волны.' },
      { at:4, title:'Строим карту волны', text:'Считываем форму волны, паузы, пики и тихие участки трека.' },
      { at:8, title:'Ищем клиппинг', text:'Находим перегрузы и резкие всплески, чтобы убрать грязь без потери атаки.' },
      { at:12, title:'Оцениваем динамику', text:'Смотрим разницу между тихими и громкими местами, сохраняем живое дыхание записи.' },
      { at:16, title:'Чистим шумовой хвост', text:'Снимаем фон, шипение и мутные остатки, не высушивая материал.' },
      { at:20, title:'Выравниваем громкость', text:'Поднимаем воспринимаемую громкость аккуратно, без плоского пережатия.' },
      { at:24, title:'Собираем частотный баланс', text:'Согласуем низ, середину и верх, чтобы трек читался цельно.' },
      { at:28, title:'Укрепляем низ', text:'Добавляем плотность басу и фундаменту микса без лишнего гула.' },
      { at:32, title:'Очищаем середину', text:'Убираем мутность в важных частотах, оставляя голос и инструменты понятными.' },
      { at:36, title:'Смягчаем резкость', text:'Контролируем колкие частоты, чтобы звук не утомлял на громкости.' },
