<style id="sw-index-orb-hit-circle-v989">
  @media(min-width:1024px){
    /* codex-index-orb-hit-circle-v989: the upload target is exactly the visible idle orb. */
    html:not(.swSaveData):not(.upload-active):not(.sw-processing-final-active) #swFastProcessOrb{
      pointer-events:none!important;
    }

    html:not(.swSaveData):not(.upload-active):not(.sw-processing-final-active) #swFastOrbTapShield{
      position:fixed!important;
      inset:auto!important;
      left:var(--sw-orb-hit-left,-9999px)!important;
      top:var(--sw-orb-hit-top,-9999px)!important;
      width:var(--sw-orb-hit-size,0px)!important;
      height:var(--sw-orb-hit-size,0px)!important;
      transform:none!important;
      border-radius:50%!important;
      clip-path:circle(50% at 50% 50%)!important;
      -webkit-clip-path:circle(50% at 50% 50%)!important;
      overflow:hidden!important;
      contain:paint!important;
    }

    html:not(.swSaveData) .swFastTopTabs,
    html:not(.swSaveData) .swFastTopCabinet{
      z-index:21474840!important;
    }
  }
</style>
<script id="sw-index-orb-hit-circle-v989-js">
  (() => {
    const desktop = window.matchMedia('(min-width:1024px)');
    let frame = 0;

    const sync = () => {
      frame = 0;
      if (!desktop.matches) return;
      const root = document.documentElement;
      const shield = document.getElementById('swFastOrbTapShield');
      const orb = document.getElementById('swFastProcessOrb');
      if (!shield || !orb || root.classList.contains('swSaveData')) return;

      const rect = orb.getBoundingClientRect();
      const size = Math.min(rect.width, rect.height);
      if (!Number.isFinite(size) || size < 1) return;
      const left = rect.left + (rect.width - size) / 2;
      const top = rect.top + (rect.height - size) / 2;

      shield.style.setProperty('--sw-orb-hit-left', left.toFixed(3) + 'px');
      shield.style.setProperty('--sw-orb-hit-top', top.toFixed(3) + 'px');
      shield.style.setProperty('--sw-orb-hit-size', size.toFixed(3) + 'px');
    };

    const schedule = () => {
      if (frame) cancelAnimationFrame(frame);
      frame = requestAnimationFrame(sync);
    };

    const observe = () => {
      const orb = document.getElementById('swFastProcessOrb');
      if (orb && 'ResizeObserver' in window) new ResizeObserver(schedule).observe(orb);
      new MutationObserver(schedule).observe(document.documentElement, {
        attributes:true,
        attributeFilter:['class']
      });
      if (document.body) {
        new MutationObserver(schedule).observe(document.body, {
          attributes:true,
          attributeFilter:['data-page-state']
        });
      }
      schedule();
    };

    window.addEventListener('load', schedule, { once:true, passive:true });
    window.addEventListener('resize', schedule, { passive:true });
    if (desktop.addEventListener) desktop.addEventListener('change', schedule);
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', observe, { once:true });
    else observe();
  })();
</script>
HTML;

