<script id="sw-processing-editorial-layout-v1-js">
(function(){
  'use strict';
  if (window.__swProcessingEditorialLayoutV1) return;
  window.__swProcessingEditorialLayoutV1 = true;

  var META_KEY = 'sunowave:processing_track_meta';
  var pendingFile = null;
  var decoderBridgeInstalled = false;

  function active(){
    var state = String(document.body && document.body.dataset ? document.body.dataset.pageState || '' : '');
    return document.documentElement.classList.contains('upload-active')
      || document.documentElement.classList.contains('sw-processing-final-active')
      || /^(uploading|processing|queued|paid-processing)$/i.test(state);
  }

  function cleanName(value){
    var name = String(value || '').trim().split(/[\\/]/).pop() || '';
    return name.replace(/\.(?:mp3|wav|flac|m4a|aac|ogg)$/i,'').trim() || 'Ваш обработанный трек';
