  if (!overlay || source.length !== 37) return;

  const heading = overlay.querySelector('#swExplainTitle');
  const intro = overlay.querySelector('#swExplainIntro');
  const hint = overlay.querySelector('.swExplainHint');
  const table = overlay.querySelector('.swExplainTable');
  if (heading) heading.textContent = 'Что сделаем';
  if (intro) intro.textContent = '37 этапов, которые начнут происходить после загрузки файла — от инфраниза до финальной проверки.';
  if (hint) hint.textContent = 'Это обещание цепочки обработки: каждый этап будет применён только там, где он нужен треку.';
  if (table) {
    table.innerHTML = '<thead><tr><th>Этап</th><th>Что сделаем</th></tr></thead><tbody>' + source.map((item, index) =>
      '<tr style="--sw-explain-delay:' + (index * .12).toFixed(2) + 's"><td>' + future(item[1]) + '</td><td>' + future(item[2]) + '</td></tr>'
    ).join('') + '</tbody>';
  }
  overlay.dataset.swExplainFuture37 = '1';
})();
</script>
