(() => {
  'use strict';
  if (window.__swIndexCopyBetweenSloganProofV1) return;
  window.__swIndexCopyBetweenSloganProofV1 = true;
  const root = document.documentElement;
  const body = document.body;
  const copy = document.querySelector('.swFastDesktopCopy');
  const slogan = document.querySelector('.swFastHeaderSlogan');
  const cards = document.querySelector('.swIndexProofMetrics');
  const heading = copy && copy.querySelector(':scope > h1');
  const lead = copy && copy.querySelector(':scope > .swFastDesktopLead');
  if (!copy || !slogan || !cards || !heading || !lead) return;
  const visible = (element) => {
    const style = getComputedStyle(element);
    const rect = element.getBoundingClientRect();
    return style.display !== 'none' && style.visibility !== 'hidden' && rect.width > 1 && rect.height > 1;
  };
  const enabled = () => window.matchMedia('(min-width:1024px)').matches
    && !root.classList.contains('swSaveData')
    && !root.classList.contains('sw-has-result-recall')
    && !root.classList.contains('upload-active')
    && !root.classList.contains('sw-processing-final-active')
    && !['uploading','processing','queued','paid-processing'].includes(body.dataset.pageState || '');
  let frame = 0;
  const sync = () => {
    frame = 0;
    if (!enabled()) {
      copy.style.removeProperty('top');
      copy.removeAttribute('data-sw-y-centered');
      return;
    }
    if (![slogan,cards,heading,lead].every(visible)) return;
    const sloganRect = slogan.getBoundingClientRect();
    const cardsRect = cards.getBoundingClientRect();
    const headingRect = heading.getBoundingClientRect();
    const leadRect = lead.getBoundingClientRect();
    const copyRect = copy.getBoundingClientRect();
    const contentTop = Math.min(headingRect.top,leadRect.top);
    const contentBottom = Math.max(headingRect.bottom,leadRect.bottom);
    const contentHeight = contentBottom - contentTop;
    const freeHeight = cardsRect.top - sloganRect.bottom;
    if (contentHeight <= 0 || freeHeight <= contentHeight) return;
    const targetContentTop = sloganRect.bottom + (freeHeight - contentHeight) / 2;
    const targetCopyTop = copyRect.top + targetContentTop - contentTop;
    if (Math.abs(copyRect.top - targetCopyTop) > .35) {
      copy.style.setProperty('top', `${targetCopyTop.toFixed(2)}px`, 'important');
    }
    copy.dataset.swYCentered = '1';
    copy.dataset.swYCenterTop = targetCopyTop.toFixed(2);
  };
  const schedule = () => {
    if (frame) cancelAnimationFrame(frame);
    frame = requestAnimationFrame(sync);
  };
  schedule();
  requestAnimationFrame(schedule);
  window.addEventListener('load', schedule, {once:true});
  window.addEventListener('resize', schedule, {passive:true});
  if ('ResizeObserver' in window) {
    const observer = new ResizeObserver(schedule);
    [slogan,cards,heading,lead].forEach((element) => observer.observe(element));
  }
  if ('MutationObserver' in window) {
    const observer = new MutationObserver(schedule);
    observer.observe(root, {attributes:true, attributeFilter:['class']});
    observer.observe(body, {attributes:true, attributeFilter:['data-page-state','class']});
  }
})();
</script>
