  const finitePositive = (value) => {
    const number = Number(value);
    return Number.isFinite(number) && number > 0 ? number : null;
  };
  const clock = (seconds) => {
    const safe = Math.max(0,Math.floor(seconds));
    const hours = Math.floor(safe/3600);
    const minutes = Math.floor((safe%3600)/60);
    const rest = safe%60;
    return hours>0
      ? String(hours).padStart(2,'0')+':'+String(minutes).padStart(2,'0')+':'+String(rest).padStart(2,'0')
      : String(minutes).padStart(2,'0')+':'+String(rest).padStart(2,'0');
  };
  const active = () => {
    const pageState = String(document.body && document.body.dataset ? document.body.dataset.pageState || '' : '');
    return document.documentElement.classList.contains('upload-active') || document.documentElement.classList.contains('sw-processing-final-active') || /^(uploading|processing|queued|paid-processing)$/i.test(pageState);
  };
