    if(label)label.textContent='\u0422\u043e\u0447\u043d\u043e \u043f\u0440\u043e\u0448\u043b\u043e';
    return eta;
  };
  const animate = (element,value) => {
    if (!element || !value) return;
    if (!element.dataset.etaCurrent || element.textContent === '--:--') { element.textContent=value; element.dataset.etaCurrent=value; return; }
    if (element.dataset.etaCurrent === value || element.dataset.etaNext === value) return;
    element.dataset.etaNext=value;
    element.classList.remove('is-time-entering');
    element.classList.add('is-time-exiting');
    clearTimeout(element.__swEtaSwapTimer);clearTimeout(element.__swEtaEnterTimer);
    element.__swEtaSwapTimer=setTimeout(() => { const next=element.dataset.etaNext||value;element.textContent=next;element.dataset.etaCurrent=next;delete element.dataset.etaNext;element.classList.remove('is-time-exiting');element.classList.add('is-time-entering');element.__swEtaEnterTimer=setTimeout(() => element.classList.remove('is-time-entering'),260); },145);
  };
