    state.done=/^(done|error|failed|cancelled|canceled)$/.test(status);
    if(hasServerClock){
      const projected=state.receivedAt ? state.elapsedBase+Math.max(0,(now-state.receivedAt)/1000) : 0;
      state.elapsedBase=Math.max(reported,projected,state.displayed);
      state.receivedAt=now;
    }else if(!state.receivedAt && status==='processing'){
      state.elapsedBase=0;
      state.receivedAt=now;
    }
    window.__swProcessingElapsed={status:state.status,elapsedSeconds:Math.floor(state.elapsedBase),source:hasServerClock?'server':'local'};
  };
  const render = () => {
    if(!active() || state.done){
      if(!active()){state.elapsedBase=0;state.receivedAt=0;state.displayed=0;}
      return;
    }
    const eta=ensure();
    if(!eta)return;
    const valueNode=eta.querySelector('.swOrbEtaMatrix__value');
    const target=state.receivedAt ? state.elapsedBase+Math.max(0,(Date.now()-state.receivedAt)/1000) : 0;
    state.displayed=Math.max(state.displayed,target);
    const value=clock(state.displayed);
    animate(valueNode,value);
    document.querySelectorAll('.swFinalOrbCopy__eta strong,.swProcessingStatusEta strong,.swEtaChip strong').forEach((node)=>{if(node.textContent!==value)node.textContent=value;});
    document.querySelectorAll('.swFinalOrbCopy__eta span,.swProcessingStatusEta span,.swEtaChip span').forEach((node)=>{node.textContent='\u0422\u043e\u0447\u043d\u043e \u043f\u0440\u043e\u0448\u043b\u043e';});
    if(window.__swProcessingElapsed)window.__swProcessingElapsed.displayedSeconds=Math.floor(state.displayed);
  };
  const originalFetch=window.fetch&&window.fetch.bind(window);
  if(originalFetch){
    window.fetch=function(input,init){
      const url=typeof input==='string'?input:String(input&&input.url||'');
      return originalFetch(input,init).then((response)=>{
        if(/(?:^|\/)status(?:_best)?\.php(?:\?|$)/i.test(url)){
          try{response.clone().json().then(ingest).catch(()=>{});}catch(_){}
        }
        return response;
      });
    };
  }
  document.addEventListener('change',(event)=>{
    if(event.target&&event.target.matches&&event.target.matches('input[type="file"]')){
      state.status='';state.elapsedBase=0;state.receivedAt=0;state.displayed=0;state.done=false;
    }
  },true);
  setInterval(render,250);render();
  new MutationObserver(render).observe(document.documentElement,{attributes:true,attributeFilter:['class']});
  if(document.body)new MutationObserver(render).observe(document.body,{attributes:true,attributeFilter:['data-page-state']});
})();
</script>
