<script id="codex-index-vinyl-result-ui-v1-js">
(() => {
  'use strict';
  if (window.__swIndexVinylResultUiV1) return;
  window.__swIndexVinylResultUiV1 = true;

  const META_KEY = 'sunowave:processing_track_meta';
  const active = () => {
    const state = String(document.body?.dataset?.pageState || '');
    return document.documentElement.classList.contains('upload-active')
      || document.documentElement.classList.contains('sw-processing-final-active')
      || /^(uploading|processing|queued|paid-processing)$/i.test(state);
  };
  const cleanName = (value) => {
    const name = String(value || '').trim().split(/[\\/]/).pop() || '';
    return name.replace(/\.(?:mp3|wav|flac|m4a|aac|ogg|aiff|aif|opus)$/i, '').trim();
  };
  const trackName = () => {
    let name = '';
    try {
      const meta = JSON.parse(localStorage.getItem(META_KEY) || 'null');
      name = cleanName(meta?.name || meta?.fileName || '');
      if (!name) name = cleanName(localStorage.getItem('sunowave:last_track_name') || '');
    } catch (_) {}
    return name || 'ВАШ ТРЕК';
  };
  const trackLabel = (rawName) => {
    const name = cleanName(rawName).replace(/\s+/g, ' ').trim();
    const normalized = name.replace(/\s*_\s*-\s*_\s*/g, ' - ').replace(/\s*_+\s*/g, ' ').trim();
    const separator = normalized.match(/\s+[-\u2013\u2014]\s+/);
    if (separator) {
      const index = separator.index || 0;
      const artist = normalized.slice(0, index).trim();
      const title = normalized.slice(index + separator[0].length).trim();
      if (artist && title) return { mode: 'split', artist, title };
    }
    const words = normalized.split(/\s+/).filter(Boolean);
    const lines = [];
    for (let index = 0; index < words.length; index += 2) lines.push(words.slice(index, index + 2).join(' '));
    return { mode: 'single', lines: lines.length ? lines : ['ВАШ ТРЕК'] };
  };
  const renderTrackLabel = (element, rawName) => {
    const parsed = trackLabel(rawName);
    element.classList.toggle('is-split', parsed.mode === 'split');
    element.classList.toggle('is-single', parsed.mode === 'single');
    element.replaceChildren();
    if (parsed.mode === 'split') {
      const artist = document.createElement('span');
      artist.className = 'swProcessingVinyl__line swProcessingVinyl__artist';
      artist.textContent = parsed.artist;
      const title = document.createElement('span');
      title.className = 'swProcessingVinyl__line swProcessingVinyl__title';
      title.textContent = parsed.title;
      element.append(artist, title);
      return;
    }
    parsed.lines.forEach((line) => {
      const node = document.createElement('span');
      node.className = 'swProcessingVinyl__line';
      node.textContent = line;
      element.appendChild(node);
    });
  };
  const stageText = () => {
    const orb = document.getElementById('swFastProcessOrb');
    const title = String(orb?.querySelector('.swFinalOrbCopy__title')?.textContent || '');
    const text = String(orb?.querySelector('.swFinalOrbCopy__text')?.textContent || '');
    return (title + ' ' + text).toLowerCase();
  };
  const technicalCopy = () => {
    const source = stageText();
    const state = String(document.body?.dataset?.pageState || '').toLowerCase();
    if (state === 'uploading' || /принимаем|приемк|приёмк|аудиофайл|загружа|waveform|карта волны|графическ.*волн/.test(source)) {
      return ['ПРИЕМКА ФАЙЛА', 'Идет приемка файла и рендеринг графической волны.'];
    }
    if (/stem|demucs|раздел/.test(source)) {
      return ['STEM SEPARATION', 'Demucs htdemucs: vocals / drums / bass / other'];
    }
    if (/reference|референ|тональ|спектр|частот|баланс/.test(source)) {
      return ['REFERENCE MATCHING', 'Спектральный профиль, динамика и stereo image сравниваются с reference'];
    }
    if (/sr|bandwidth|высок|harmonic|гармони/.test(source)) {
      return ['BANDWIDTH EXTENSION', 'AudioSR / harmonic recovery: контроль полосы и естественных гармоник'];
    }
    if (/vocal|голос|сибил|bass|бас|drum|барабан|other|инструмент/.test(source)) {
      return ['PER-STEM PROCESSING', 'Индивидуальная коррекция stem: EQ, dynamics, phase и transient control'];
    }
    if (/master|финал|qa|провер|render|рендер/.test(source)) {
      return ['FINAL MASTER QA', 'True peak, mono compatibility, clipping и source-preserved fallback'];
    }
    return ['AUDIO PROCESSING', 'Спектральный анализ, коррекция динамики и контроль фазовой когерентности'];
  };
  const ensureVinyl = (orb) => {
    if (!orb) return null;
    let vinyl = orb.querySelector(':scope>.swProcessingVinyl');
    if (!vinyl) {
      vinyl = document.createElement('div');
      vinyl.className = 'swProcessingVinyl';
      vinyl.setAttribute('aria-hidden', 'true');
      vinyl.innerHTML = '<div class="swProcessingVinyl__face"><img class="swProcessingVinyl__image" src="/assets/processing/plast2.png?v=20260901_1" alt=""><span class="swProcessingVinyl__track-name"></span></div>';
      orb.appendChild(vinyl);
    }
    return vinyl;
  };
  const fitTitle = (title) => {
    if (!title) return;
    const width = Math.max(36, title.getBoundingClientRect().width || 0);
    const lines = Array.from(title.querySelectorAll('.swProcessingVinyl__line'));
    if (!lines.length) return;
    const canvas = fitTitle.canvas || (fitTitle.canvas = document.createElement('canvas'));
    const context = canvas.getContext('2d');
    if (!context) return;
    let size = window.innerWidth <= 380 ? 11 : window.innerWidth <= 1023 ? 13 : 18;
    const minSize = width < 170 ? 7 : 8;
    const measure = () => lines.reduce((max, line) => {
      const style = getComputedStyle(line);
      context.font = `${style.fontWeight} ${style.fontSize} ${style.fontFamily}`;
      return Math.max(max, context.measureText(line.textContent || '').width);
    }, 0);
    title.style.setProperty('font-size', `${size}px`, 'important');
    let measured = measure();
    while (measured > width * .90 && size > minSize) {
      size -= .5;
      title.style.setProperty('font-size', `${size}px`, 'important');
      measured = measure();
    }
    title.style.setProperty('font-size', `${size.toFixed(1)}px`, 'important');
    title.style.setProperty('--sw-vinyl-title-scale', Math.min(1, (width * .92) / Math.max(measured, 1)).toFixed(3));
  };
  const syncTechnicalCopy = () => {
    if (!active() || window.innerWidth > 1023) return;
    const rail = document.getElementById('swProcessingStatusRail');
    if (!rail) return;
    const title = rail.querySelector('.swProcessingStatusTitle');
    const text = rail.querySelector('.swProcessingStatusText');
    const copy = technicalCopy();
    if (title && title.textContent !== copy[0]) title.textContent = copy[0];
    if (text && text.textContent !== copy[1]) text.textContent = copy[1];
  };
  const sync = () => {
    const orb = document.getElementById('swFastProcessOrb');
    if (!orb) return;
    const vinyl = ensureVinyl(orb);
    if (!vinyl) return;
    const live = active();
    vinyl.classList.toggle('is-live', live);
    if (live) {
      const title = vinyl.querySelector('.swProcessingVinyl__track-name');
      if (title) {
        const next = trackName();
        if (title.dataset.swTrackName !== next) {
          renderTrackLabel(title, next);
          title.dataset.swTrackName = next;
        }
        fitTitle(title);
      }
      syncTechnicalCopy();
    }
  };
  const boot = () => {
    sync();
    new MutationObserver(sync).observe(document.documentElement, {childList:true,subtree:true,attributes:true,attributeFilter:['class']});
    if (document.body) new MutationObserver(sync).observe(document.body, {childList:true,subtree:true,attributes:true,attributeFilter:['data-page-state','class']});
    window.addEventListener('resize', sync, {passive:true});
    window.setInterval(sync, 600);
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot, {once:true});
  else boot();
})();
</script>
