        if (is_string($recallWaveSource) && preg_match(
            '~(<style\s+id="codex-result-recall-wave-centered-v2">.*?</style>\s*<script\s+id="codex-result-recall-wave-centered-v2-js">.*?</script>)~is',
            $recallWaveSource,
            $recallWaveMatch
        )) {
            $html = $injectBeforeBody($html, (string)$recallWaveMatch[1]);
        }
    }
    $uploadOrbCloudGearMarker = 'codex-index-upload-orb-cloud-gear-v1-css';
    if (stripos($html, $uploadOrbCloudGearMarker) === false) {
        $uploadOrbCloudGearSource = @file_get_contents(__FILE__);
        if (is_string($uploadOrbCloudGearSource) && preg_match(
            '~(<style\s+id="codex-index-upload-orb-cloud-gear-v1-css">.*?</style>\s*<script\s+id="codex-index-upload-orb-cloud-gear-v1-js">.*?</script>)~is',
            $uploadOrbCloudGearSource,
            $uploadOrbCloudGearMatch
        )) {
            $html = $injectBeforeBody($html, (string)$uploadOrbCloudGearMatch[1]);
        }
    }
    $processingCopySplitMarker = 'codex-index-processing-copy-split-v1-css';
    if (stripos($html, $processingCopySplitMarker) === false) {
        $processingCopySplitSource = @file_get_contents(__FILE__);
        if (is_string($processingCopySplitSource) && preg_match(
            '~(<style\s+id="codex-index-processing-copy-split-v1-css">.*?</style>\s*<script\s+id="codex-index-processing-copy-split-v1-js">.*?</script>)~is',
            $processingCopySplitSource,
            $processingCopySplitMatch
        )) {
            $html = $injectBeforeBody($html, (string)$processingCopySplitMatch[1]);
        }
    }
    return $html;
}

$defaultFastShellRequest = PHP_SAPI !== 'cli'
    && ($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'GET'
    && !$ok
    && !$logoutReset
    && !$paidReturn
    && !$hasReturnJob
    && !isset($_GET['full'])
    && !isset($_GET['legacy']);

if ($defaultFastShellRequest) {
    $fastShell = __DIR__ . '/engine/codex_index_fast_shell_v604.php';
    if (is_file($fastShell)) {
