            $swFastShellHtml = (string)ob_get_clean();
            echo sw_index_prepare_homepage_html($swFastShellHtml);
            exit;
        }
    }
}

$bootstrap = [
    'csrf' => (string)$_SESSION['csrf'],
    'jobId' => $returnJob,
    'ok' => $ok,
    'paid' => $paidReturn,
    'logout' => $logoutReset,
