  <title>Результат обработки аудио | SUNO WAVE</title>
  <style>
    :root{
      color-scheme:dark;
      --bg:#050a12;
      --panel:#08131f;
      --text:#fff;
      --muted:rgba(255,255,255,.68);
      --faint:rgba(255,255,255,.45);
      --line:rgba(255,255,255,.10);
      --blue:#9bc3eb;
      --gold:#ffc857;
      --gold2:#ffd36a;
      --green:#24d366;
      --green2:#189d45;
      --danger:#ff6969;
      --radius-xl:28px;
      --radius-lg:22px;
      font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;
    }
    *{box-sizing:border-box}
    html,body{min-height:100%;margin:0}
    body{
      background:
        radial-gradient(circle at 65% -8%,rgba(255,200,87,.10),transparent 34%),
        radial-gradient(circle at 15% 5%,rgba(73,144,255,.12),transparent 32%),
        linear-gradient(180deg,#07111d 0%,#03060c 100%);
      color:var(--text);
      overflow:hidden;
    }
    body::before{
      content:"";
      position:fixed;
      inset:0;
      pointer-events:none;
      background:
        linear-gradient(90deg,rgba(2,7,14,.82),rgba(2,7,14,.52)),
        radial-gradient(circle at 50% 0%,rgba(42,121,255,.10),transparent 42%);
    }
    a{color:inherit}
    button{font:inherit}
    .result-only-screen{
      min-height:100svh;
      display:grid;
      place-items:center;
      padding:24px;
      position:relative;
      z-index:1;
    }
    .modal-overlay{
      position:fixed;
      inset:0;
      z-index:50;
      display:flex;
      align-items:center;
      justify-content:center;
      padding:24px;
      background:rgba(2,7,14,.66);
      backdrop-filter:blur(14px);
    }
    .modal{
      width:min(1080px,100%);
      max-height:calc(100svh - 48px);
      overflow:auto;
      position:relative;
      padding:34px;
      border-radius:var(--radius-xl);
      background:
        radial-gradient(circle at 15% 0%,rgba(73,144,255,.08),transparent 34%),
        linear-gradient(180deg,#08131f 0%,#050a12 100%);
      border:1px solid rgba(120,190,255,.18);
      box-shadow:0 28px 90px rgba(0,0,0,.65),inset 0 1px 0 rgba(255,255,255,.05);
    }
    .modal-close{
      position:absolute;
      z-index:20;
      top:22px;
      right:22px;
      width:44px;
      height:44px;
      display:grid;
      place-items:center;
      border-radius:50%;
      border:1px solid rgba(255,255,255,.12);
      background:rgba(255,255,255,.045);
      color:rgba(255,255,255,.9);
      font-size:30px;
      line-height:1;
      text-decoration:none;
      pointer-events:auto!important;
      cursor:pointer;
    }
    .modal-close:hover{background:rgba(255,255,255,.09)}
    .result-header{padding-right:62px;margin-bottom:26px}
    .result-header h1{margin:0 0 8px;font-size:clamp(34px,4.4vw,56px);line-height:1;font-weight:950;letter-spacing:.02em}
    .result-header p{margin:0;color:var(--muted);font-size:17px;line-height:1.45}
    .result-grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(320px,.85fr);gap:20px;align-items:stretch}
    .compare-column{display:flex;flex-direction:column;gap:16px}
    .audio-card{
      position:relative;
      min-height:230px;
      padding:28px;
      overflow:hidden;
      border-radius:var(--radius-lg);
      background:rgba(255,255,255,.035);
      border:1px solid rgba(255,255,255,.08);
    }
    .audio-card::before{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(circle at 85% 12%,rgba(120,190,255,.07),transparent 28%)}
    .audio-card.before{border-color:rgba(120,190,255,.16)}
    .audio-card.after{
      background:radial-gradient(circle at 85% 8%,rgba(255,200,87,.12),transparent 34%),rgba(255,255,255,.035);
      border-color:rgba(255,200,87,.42);
      box-shadow:0 0 38px rgba(255,190,70,.08),inset 0 1px 0 rgba(255,255,255,.05)
    }
    .audio-top{position:relative;z-index:1;display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:18px}
    .title-pill{display:inline-flex;align-items:center;gap:10px;min-height:42px;padding:0 18px;border-radius:10px;font-size:18px;font-weight:850;background:rgba(125,179,230,.11);color:rgba(235,247,255,.96)}
    .after .title-pill{background:rgba(255,200,87,.13);color:rgba(255,240,195,.98)}
    .meta{display:flex;flex-direction:column;align-items:flex-end;gap:8px}
    .badge-row{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap}
    .size-badge,.improved-badge{min-height:34px;display:inline-flex;align-items:center;padding:0 14px;border-radius:9px;border:1px solid;background:rgba(255,255,255,.035);font-size:14px;font-weight:800;white-space:nowrap}
    .before .size-badge{color:rgba(217,235,255,.86);border-color:rgba(140,190,255,.15)}
    .after .size-badge,.improved-badge{color:var(--gold2);border-color:rgba(255,200,87,.34);background:rgba(255,200,87,.08)}
    .tech{font-size:14px;line-height:1;white-space:nowrap;color:rgba(166,194,225,.78)}
    .after .tech{color:rgba(255,211,106,.92)}
    .audio-desc{position:relative;z-index:1;margin:0 0 20px;color:var(--muted);font-size:17px;line-height:1.45}
    .player-row{position:relative;z-index:1;display:grid;grid-template-columns:78px minmax(0,1fr);gap:22px;align-items:center}
    .play-btn{width:70px;height:70px;border-radius:50%;display:grid;place-items:center;border:1px solid rgba(147,205,255,.45);background:radial-gradient(circle at 50% 45%,rgba(255,255,255,.08),transparent 65%),rgba(255,255,255,.035);color:#fff;font-size:28px;cursor:pointer;box-shadow:0 0 28px rgba(120,190,255,.08)}
    .after .play-btn{border-color:rgba(255,200,87,.65);box-shadow:0 0 30px rgba(255,200,87,.13)}
    .wave-shell{height:82px;width:100%;position:relative;overflow:hidden;mask-image:linear-gradient(to right,transparent,black 5%,black 95%,transparent)}
    .wave-img{width:100%;height:100%;display:none;object-fit:fill;opacity:.95;filter:drop-shadow(0 0 9px rgba(140,190,255,.14))}
    .wave-img.is-ready{display:block}
    .wave-fallback{position:absolute;inset:0;background-repeat:repeat-x;background-size:6px 100%}
    .before .wave-fallback{background-image:linear-gradient(90deg,rgba(155,195,235,.42) 0 2px,transparent 2px 6px)}
    .after .wave-fallback{background-image:linear-gradient(90deg,rgba(255,199,54,.82) 0 2px,transparent 2px 6px)}
    .time-row{position:relative;z-index:1;display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:14px;align-items:center;margin-top:14px;color:rgba(255,255,255,.76);font-size:18px}
    .progress-line{height:2px;position:relative;background:rgba(255,255,255,.16);border-radius:999px}
    .progress-line span{position:absolute;left:0;top:50%;width:12px;height:12px;transform:translateY(-50%);border-radius:50%;background:#b8d4f0}
    .after .progress-line span{background:var(--gold)}
    .purchase-card{padding:34px 28px;border-radius:var(--radius-lg);background:radial-gradient(circle at 50% 0%,rgba(36,211,102,.18),transparent 35%),linear-gradient(180deg,rgba(12,35,29,.78),rgba(7,19,23,.88));border:1px solid rgba(50,213,110,.26);display:flex;flex-direction:column;align-items:center;text-align:center}
    .purchase-icon{position:relative;width:76px;height:76px;border-radius:50%;display:grid;place-items:center;border:1px solid rgba(88,238,123,.45);background:rgba(40,211,102,.10);box-shadow:0 0 36px rgba(40,211,102,.15)}
    .purchase-icon span{width:30px;height:34px;display:block;background:repeating-linear-gradient(90deg,rgba(255,255,255,.92) 0 3px,transparent 3px 8px);border-radius:999px}
    .purchase-icon b{position:absolute;right:2px;bottom:4px;width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:#74ef5f;color:#06200b;font-size:15px}
    .purchase-card h2{margin:22px 0 12px;font-size:25px;line-height:1.15;font-weight:950}
    .purchase-card p{max-width:280px;margin:0 auto 24px;color:var(--muted);font-size:16px;line-height:1.5}
    .price{width:100%;margin-bottom:24px;padding:17px 20px;border-radius:14px;background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.055);color:#79ef69;font-size:42px;line-height:1;font-weight:950;letter-spacing:.05em}
    .benefits{width:100%;display:grid;gap:13px;margin:0 0 26px;padding:0;list-style:none;text-align:left}
    .benefits li{position:relative;padding-left:32px;color:rgba(255,255,255,.76);font-size:15px;line-height:1.25}
    .benefits li::before{content:"✓";position:absolute;left:0;top:-2px;width:19px;height:19px;border-radius:50%;display:grid;place-items:center;color:#7bf76d;border:1px solid rgba(123,247,109,.65);font-size:12px}
    .main-cta,.secondary-cta{width:100%;display:inline-flex;align-items:center;justify-content:center;text-decoration:none;cursor:pointer}
    .main-cta{min-height:58px;gap:12px;border:0;border-radius:14px;background:linear-gradient(135deg,var(--green) 0%,var(--green2) 100%);color:#fff;font-size:16px;font-weight:900;box-shadow:0 14px 34px rgba(36,211,102,.28)}
    .main-cta:hover{transform:translateY(-1px);box-shadow:0 18px 44px rgba(36,211,102,.36)}
    .secondary-cta{min-height:50px;margin-top:12px;border-radius:13px;border:1px solid rgba(255,255,255,.13);background:rgba(255,255,255,.035);color:rgba(255,255,255,.92);font-size:15px;font-weight:850}
    .safe-line{width:100%;margin-top:auto;padding-top:18px;color:rgba(255,255,255,.52);font-size:13px;line-height:1.2}
    .security-note{display:flex;align-items:center;gap:16px;margin-top:18px;padding:16px 22px;border-radius:16px;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.07)}
    .security-icon{width:42px;height:42px;flex:0 0 auto;border-radius:12px;display:grid;place-items:center;color:#9cc7ff;border:1px solid rgba(156,199,255,.22);background:rgba(156,199,255,.07)}
    .security-note strong{display:block;color:rgba(255,255,255,.9);font-size:16px;margin-bottom:3px}
    .security-note p{margin:0;color:rgba(255,255,255,.52);font-size:14px;line-height:1.35}
    .modal.is-loading .result-grid{opacity:.44;filter:saturate(.8)}
    .loading-panel{display:none;margin-top:16px;padding:18px;border-radius:18px;border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.04);color:var(--muted)}
    .modal.is-loading .loading-panel{display:block}
    .loading-bar{height:4px;margin-top:12px;border-radius:999px;background:rgba(255,255,255,.1);overflow:hidden}
    .loading-bar span{display:block;width:36%;height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--gold),var(--green));animation:loadslide 1.2s ease-in-out infinite alternate}
    @keyframes loadslide{from{transform:translateX(-15%)}to{transform:translateX(185%)}}
    .reward-overlay{position:fixed;inset:0;z-index:70;display:none;align-items:center;justify-content:center;padding:18px;background:rgba(2,7,14,.72);backdrop-filter:blur(16px)}
    .reward-overlay.show{display:flex}
    .reward-card{width:min(520px,100%);position:relative;padding:30px;border-radius:24px;border:1px solid rgba(50,213,110,.28);background:radial-gradient(circle at 50% 0%,rgba(36,211,102,.20),transparent 38%),linear-gradient(180deg,#0a1c1a,#050a12);box-shadow:0 28px 90px rgba(0,0,0,.64);text-align:center}
    .reward-card h2{margin:12px 0 10px;font-size:32px;line-height:1.05}
    .reward-card p{margin:0 0 20px;color:var(--muted);line-height:1.5}
    .reward-close{position:absolute;top:14px;right:14px;width:38px;height:38px;border-radius:50%;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.05);color:#fff;font-size:24px;cursor:pointer}
    .toast{position:fixed;left:50%;bottom:18px;z-index:90;transform:translateX(-50%) translateY(120%);width:min(460px,calc(100% - 24px));padding:14px 16px;border-radius:16px;border:1px solid rgba(255,255,255,.12);background:rgba(8,19,31,.92);box-shadow:0 16px 44px rgba(0,0,0,.42);opacity:0;transition:.22s ease}
    .toast.show{opacity:1;transform:translateX(-50%) translateY(0)}
    .toast strong{display:block;margin-bottom:3px}.toast span{color:var(--muted);font-size:14px}
    .hidden-audio{position:fixed!important;left:-9999px!important;top:0!important;width:1px!important;height:1px!important;opacity:0!important;overflow:hidden!important;pointer-events:none!important}

    /* === SUNO WAVE SAAS REAL WAVEFORM PLAYER START === */
    .swWaveSaasPlayerRow{display:block!important;width:100%!important;grid-template-columns:1fr!important;gap:0!important}
    .swWaveSaasPlayer{
      --progress:0%;
      --accent:#9bc3eb;
      --accent2:#39a5ff;
      --glow:rgba(57,165,255,.24);
      position:relative;
      width:100%;
      min-height:178px;
      padding:16px;
      border-radius:24px;
      overflow:hidden;
      isolation:isolate;
      border:1px solid rgba(155,195,235,.18);
      background:
        radial-gradient(circle at 12% 0%,rgba(155,195,235,.12),transparent 36%),
        linear-gradient(180deg,rgba(255,255,255,.054),rgba(255,255,255,.026));
      box-shadow:
        0 22px 62px rgba(0,0,0,.30),
        inset 0 1px 0 rgba(255,255,255,.08);
    }
    .swWaveSaasPlayer.is-result{
      --accent:#ffd36a;
      --accent2:#24d366;
      --glow:rgba(255,200,87,.30);
      border-color:rgba(255,200,87,.38);
      background:
        radial-gradient(circle at 80% -10%,rgba(255,200,87,.16),transparent 38%),
        radial-gradient(circle at 12% 0%,rgba(36,211,102,.10),transparent 38%),
        linear-gradient(180deg,rgba(255,255,255,.058),rgba(255,255,255,.028));
    }
    .swWaveSaasPlayer::before{
      content:"";
      position:absolute;
      inset:-90%;
      z-index:-2;
      background:conic-gradient(from 125deg,transparent,rgba(255,255,255,.14),transparent,var(--glow),transparent);
      opacity:.58;
      animation:swWaveSaasGlow 8s linear infinite;
      pointer-events:none;
    }
    .swWaveSaasPlayer::after{
      content:"";
      position:absolute;
      inset:1px;
      z-index:-1;
      border-radius:23px;
      background:
        linear-gradient(180deg,rgba(5,10,18,.20),rgba(5,10,18,.58)),
        radial-gradient(circle at 50% 0%,rgba(255,255,255,.045),transparent 62%);
      pointer-events:none;
    }
    .swWaveSaasTop{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:12px}
    .swWaveSaasTitle{display:flex;align-items:center;gap:10px;min-width:0}
    .swWaveSaasPulse{
      width:11px;height:11px;border-radius:50%;
      background:var(--accent);
      box-shadow:0 0 0 6px color-mix(in srgb,var(--accent) 16%,transparent),0 0 22px var(--accent);
      flex:0 0 auto;
    }
    .swWaveSaasTitle b{display:block;color:rgba(255,255,255,.96);font-size:15px;line-height:1;font-weight:950;white-space:nowrap}
    .swWaveSaasTitle small{display:block;margin-top:5px;color:rgba(255,255,255,.52);font-size:10px;line-height:1;text-transform:uppercase;letter-spacing:.16em;font-weight:900}
    .swWaveSaasBadge{
      min-height:30px;display:inline-flex;align-items:center;padding:0 11px;border-radius:999px;
      color:var(--accent);border:1px solid color-mix(in srgb,var(--accent) 42%,transparent);
      background:color-mix(in srgb,var(--accent) 10%,transparent);
      font-size:11px;font-weight:950;text-transform:uppercase;letter-spacing:.10em;white-space:nowrap;
    }
    .swWaveSaasBody{display:grid;grid-template-columns:56px minmax(0,1fr);gap:14px;align-items:center}
    .swWaveSaasPlay{
      width:56px;height:56px;border-radius:18px;border:1px solid color-mix(in srgb,var(--accent) 46%,transparent);
      background:
        radial-gradient(circle at 50% 26%,rgba(255,255,255,.18),transparent 58%),
        color-mix(in srgb,var(--accent) 13%,rgba(255,255,255,.03));
      color:#fff;display:grid;place-items:center;cursor:pointer;font-size:21px;font-weight:950;
      box-shadow:0 14px 34px color-mix(in srgb,var(--accent) 18%,transparent), inset 0 1px 0 rgba(255,255,255,.12);
      transition:transform .16s ease, box-shadow .16s ease, border-color .16s ease;
    }
    .swWaveSaasPlay:hover{transform:translateY(-1px);border-color:color-mix(in srgb,var(--accent) 78%,transparent);box-shadow:0 18px 42px color-mix(in srgb,var(--accent) 25%,transparent), inset 0 1px 0 rgba(255,255,255,.16)}
    .swWaveSaasPlay:active{transform:translateY(0) scale(.985)}
    .swWaveSaasStage{
      position:relative;height:86px;border-radius:18px;overflow:hidden;cursor:pointer;
      border:1px solid rgba(255,255,255,.075);
      background:
        linear-gradient(90deg,rgba(255,255,255,.035),rgba(255,255,255,.010)),
        rgba(0,0,0,.16);
      box-shadow:inset 0 1px 0 rgba(255,255,255,.04);
      user-select:none;
    }
    .swWaveImage{
      position:absolute;inset:0;width:100%;height:100%;object-fit:fill;display:block;
      opacity:0;transition:opacity .18s ease, filter .18s ease;
      pointer-events:none;
    }
    .swWaveSaasPlayer.is-wave-ready .swWaveImage{opacity:.55}
    .swWaveSaasPlayer.is-wave-ready .swWaveBase{filter:grayscale(.22) brightness(1.16) contrast(1.12) drop-shadow(0 0 12px color-mix(in srgb,var(--accent) 14%,transparent))}
    .swWaveFill{
      position:absolute;inset:0;width:var(--progress);max-width:100%;min-width:0;overflow:hidden;
      border-right:2px solid color-mix(in srgb,var(--accent) 92%,white 8%);
      box-shadow:8px 0 26px color-mix(in srgb,var(--accent) 22%,transparent);
      transition:width .09s linear;
      pointer-events:none;
    }
    .swWaveSaasPlayer.is-wave-ready .swWaveFill .swWaveImage{opacity:1;filter:brightness(1.55) saturate(1.35) contrast(1.18) drop-shadow(0 0 12px var(--accent))}
    .swWaveGrid{
      position:absolute;inset:0;opacity:.22;
