  #resultModal .audio-card.after .swWaveSaasStage::before{content:"";position:absolute;left:0;right:0;top:-10%;bottom:-10%;z-index:4;width:100%;pointer-events:none;background:linear-gradient(90deg,transparent 0,transparent calc(var(--progress,0%) - 3px),rgba(255,219,86,.20) calc(var(--progress,0%) - 3px),rgba(255,159,28,.82) var(--progress,0%),rgba(255,219,86,.20) calc(var(--progress,0%) + 3px),transparent calc(var(--progress,0%) + 3px));filter:drop-shadow(0 0 12px rgba(255,159,28,.58))}
