  var CARD_KEYWORDS = /(анализир|подготавливаем|подготавливаем буфер|подготавливаем|считываем спектр|готовим трек|извлекаем|очищаем|финализируем|обработка)/i;
  var TITLE_RE = /(анализир\s*уем\s+файл|анализируем\s+файл|подготавливаем\s+буфер|извлекаем\s+вокал|очищаем\s+трек|финализируем\s+результат|готовим\s+результат|собираем\s+чистый\s+мастер)/i;
  var BODY_RE = /(считываем\s+спектр|пики\s+громкости|готовим\s+трек|можно\s+оставить\s+вкладку|результат\s+появится\s+здесь|автоматически|подождите|идет\s+обработка)/i;
  var EYEBROW_RE = /(пламя\s+работает|обработка\s+запущена|идет\s+обработка|сейчас\s+работаем)/i;

  var STAGES = [
    { re: /(анализир|считываем\s+спектр|громкости|паузы)/i, total: 22, floor: 10 },
    { re: /(буфер|подготавливаем)/i, total: 36, floor: 12 },
    { re: /(извлекаем|разделяем|нейросет|удаляем\s+вокал|отделяем)/i, total: 68, floor: 16 },
    { re: /(очищаем|чистый\s+мастер|шумы|баланс|обработке)/i, total: 92, floor: 18 },
    { re: /(финализ|сохраняем|готовим\s+результат|почти\s+готово)/i, total: 112, floor: 10 },
    { re: /(готово|результат\s+готов)/i, total: 0, floor: 0 }
  ];

  function norm(s){ return String(s || '').replace(/\s+/g,' ').trim(); }
  function escapeRegExp(s){ return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
  function secsToClock(sec){
    sec = Math.max(0, Math.round(sec));
    var m = Math.floor(sec / 60);
    var s = sec % 60;
    return String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0');
  }

  function guessJobKey(){
    try {
      var u = new URL(location.href);
      var q = u.searchParams.get('job') || u.searchParams.get('id');
      if (q) return q;
    } catch(e) {}
    var dataJob = document.body && (document.body.dataset.job || document.body.getAttribute('data-job'));
    if (dataJob) return dataJob;
    var m = document.documentElement.innerHTML.match(/\b[a-f0-9]{32}\b/);
    return m ? m[0] : 'global';
  }

  function processStartStorageKey(){ return 'sw_processing_started_at_' + guessJobKey(); }

  function getStartedAt(){
    var key = processStartStorageKey();
    var existing = parseInt(sessionStorage.getItem(key) || '', 10);
    if (existing > 0) return existing;
    var now = Date.now();
    sessionStorage.setItem(key, String(now));
    return now;
  }

  function clearStartedAt(){
    try { sessionStorage.removeItem(processStartStorageKey()); } catch(e) {}
  }

  function active(){
    var state = String(document.body && document.body.dataset ? document.body.dataset.pageState || '' : '');
    return document.documentElement.classList.contains('upload-active')
      || document.documentElement.classList.contains('sw-processing-final-active')
      || /^(uploading|processing|queued|paid-processing)$/i.test(state);
  }

  function findCard(){
    if (!active() || document.getElementById('swFastProcessOrb')) return null;
    var all = Array.prototype.slice.call(document.querySelectorAll('div,section,article'));
    var best = null;
    var bestScore = -1;

    all.forEach(function(el){
      if (!el || !el.innerText) return;
      var text = norm(el.innerText);
      if (!CARD_KEYWORDS.test(text)) return;
      if (text.length < 24 || text.length > 450) return;
      var rect = el.getBoundingClientRect();
      if (rect.width < 180 || rect.height < 140) return;
      var score = 0;
      if (TITLE_RE.test(text)) score += 4;
      if (BODY_RE.test(text)) score += 3;
      if (EYEBROW_RE.test(text)) score += 2;
      if (rect.left > window.innerWidth * 0.42) score += 1;
      if (rect.top < window.innerHeight * 0.55) score += 1;
      if (score > bestScore) { best = el; bestScore = score; }
    });

    return best;
  }

  function textNodesWithin(card){
    return Array.prototype.slice.call(card.querySelectorAll('h1,h2,h3,h4,p,span,div,strong,b,small'));
  }

  function ensureStructure(card){
    if (!card) return null;
    card.classList.add('swEtaProcessingCard');

    var items = textNodesWithin(card).filter(function(el){
      return norm(el.textContent).length > 0;
    });

    items.forEach(function(el){
      var t = norm(el.textContent)
        .replace(/Анализир\s*уем/gi,'Анализируем')
        .replace(/Анализир\s+уем/gi,'Анализируем');
      if (t !== norm(el.textContent)) el.textContent = t;

      if (/^сек$/i.test(t)) {
        el.classList.add('swEtaHide');
        return;
      }
      if (EYEBROW_RE.test(t) && t.length <= 36) el.classList.add('swEtaEyebrow');
      if (TITLE_RE.test(t) && t.length <= 48) el.classList.add('swEtaTitle');
      if (BODY_RE.test(t) && t.length <= 180) el.classList.add('swEtaBody');
    });

    var eyebrow = card.querySelector('.swEtaEyebrow');
    var title = card.querySelector('.swEtaTitle');
    var body = card.querySelector('.swEtaBody');

    if (!eyebrow) {
      eyebrow = document.createElement('div');
      eyebrow.className = 'swEtaEyebrow';
      eyebrow.textContent = 'ИДЁТ ОБРАБОТКА';
      card.insertBefore(eyebrow, card.firstChild);
    }

    if (!title) {
      title = document.createElement('div');
      title.className = 'swEtaTitle';
      title.textContent = 'Анализируем файл';
      card.appendChild(title);
    }

    if (!body) {
      body = document.createElement('div');
      body.className = 'swEtaBody';
      body.textContent = 'Считываем спектр, пики громкости и паузы. Готовим трек к аккуратной обработке.';
      card.appendChild(body);
    }

    var eta = card.querySelector('.swEtaChip');
    if (!eta) {
      eta = document.createElement('div');
      eta.className = 'swEtaChip';
      eta.innerHTML = '<span>Точно прошло</span> <strong>00:00</strong>';
      card.appendChild(eta);
    }

    var hint = card.querySelector('.swEtaHint');
    if (!hint) {
      hint = document.createElement('div');
      hint.className = 'swEtaHint';
      hint.textContent = 'Не закрывайте вкладку — результат автоматически появится здесь. Обычно это занимает 1–2 минуты.';
      card.appendChild(hint);
    }

    var dotOwner = null;
    Array.prototype.slice.call(card.children).forEach(function(ch){
      var txt = norm(ch.textContent);
      if (!txt) return;
      if (/^[.\-–—•\s]{3,}$/.test(txt) || txt.indexOf('—') >= 0 || txt.indexOf('•') >= 0) {
        dotOwner = ch;
      }
    });
    if (dotOwner) dotOwner.classList.add('swEtaDots');

    return {card:card, eyebrow:eyebrow, title:title, body:body, eta:eta, hint:hint};
  }

  function parsePercent(){
    var txt = document.body ? document.body.innerText : '';
    var m = txt.match(/(^|\s)(\d{1,3})\s*%/m);
    if (!m) return null;
    var p = parseInt(m[2], 10);
    if (!isFinite(p) || p < 0 || p > 100) return null;
    return p;
  }

    function getStageMeta(titleText, bodyText){
      var text = norm((titleText || '') + ' ' + (bodyText || ''));
      for (var i=0; i<STAGES.length; i++) {
        if (STAGES[i].re.test(text)) return STAGES[i];
      }
      return { total: 90, floor: 15 };
    }

    function estimateRemainingSeconds(percent, stage, startedAt){
      var elapsed = Math.max(0, Math.round((Date.now() - startedAt) / 1000));
      var pct = clamp(percent || 0, 0, 99.5);
      var stageTotal = Math.max(20, Number(stage && stage.total) || 90);
      var stageFloor = Math.max(6, Number(stage && stage.floor) || 12);
      var projectedTotal = pct > 3 ? elapsed / Math.max(0.05, pct / 100) : stageTotal;
      var blendedTotal = Math.round((projectedTotal * 0.68) + (stageTotal * 0.32));
      var remaining = blendedTotal - elapsed;
      var stageTail = Math.max(8, Math.round((6 - Math.min(5, stageTotal / 20)) * 3));
      remaining = Math.max(stageFloor, remaining, stageTail);
      return Math.min(240, Math.max(6, remaining));
    }

    function updateEta(structure){
      if (!structure) return;

    var titleText = norm(structure.title.textContent || '');
    var bodyText = norm(structure.body.textContent || '');
    var stage = getStageMeta(titleText, bodyText);

    if (/готово|результат\s+готов/i.test(titleText + ' ' + bodyText)) {
      structure.eta.innerHTML = '<span>Точно прошло</span> <strong>00:00</strong>';
      structure.hint.textContent = 'Результат готов. Сейчас покажем его внизу страницы.';
      clearStartedAt();
      return;
    }

      var startedAt = getStartedAt();
      var elapsed = Math.max(0, Math.round((Date.now() - startedAt) / 1000));
      structure.eta.innerHTML = '<span>Точно прошло</span> <strong>' + secsToClock(elapsed) + '</strong>';
      structure.hint.textContent = 'Обработка продолжается. Результат автоматически появится здесь после завершения.';
    }

  var lastStructure = null;

  function apply(){
    var card = findCard();
    if (!card) return;
    lastStructure = ensureStructure(card);
    updateEta(lastStructure);
  }

  function start(){
    apply();
    setInterval(function(){ if (document.visibilityState !== 'hidden') apply(); }, 1000);
    new MutationObserver(function(){ apply(); }).observe(document.documentElement, {
      childList:true,
      subtree:true,
      characterData:true
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start, {once:true});
  } else {
    start();
  }
})();
</script>

