<script id="sw-processing-sun-only-final-v1-js">
(function(){
  if (window.__swProcessingSunOnlyFinalV1) return;
  window.__swProcessingSunOnlyFinalV1 = true;

  function active(){
    var state = String(document.body && document.body.dataset ? document.body.dataset.pageState || '' : '');
    return document.documentElement.classList.contains('upload-active')
      || document.documentElement.classList.contains('sw-processing-final-active')
      || /^(uploading|processing|queued|paid-processing)$/i.test(state);
  }

  function setHidden(el, on){
    if(!el) return;
    if(on){
      el.classList.add('sw-processing-duplicate-status');
      el.style.setProperty('display','none','important');
      el.style.setProperty('visibility','hidden','important');
      el.style.setProperty('opacity','0','important');
      el.style.setProperty('pointer-events','none','important');
    } else {
      el.style.removeProperty('display');
      el.style.removeProperty('visibility');
      el.style.removeProperty('opacity');
      el.style.removeProperty('pointer-events');
    }
  }

  function sync(){
    var on = active();
    document.querySelectorAll('.swFastDesktopCopy,.swIndexProofMetrics,.swProcessingTrust,.swFastLegalConsent,#swProcessingTimer').forEach(function(el){
      setHidden(el, on);
    });
  }

  new MutationObserver(sync).observe(document.documentElement, {attributes:true, attributeFilter:['class']});
  if(document.body) new MutationObserver(sync).observe(document.body, {attributes:true, attributeFilter:['data-page-state']});
  window.addEventListener('DOMContentLoaded', sync, {once:true});
  window.setInterval(sync, 180);
  sync();
})();
</script>

