<script id="sw-result-recall-layout-senior-v1-js">
(() => {
  const sync = () => {
    const recall = document.documentElement.classList.contains('sw-has-result-recall');
    document.querySelectorAll('.swExplainCloud').forEach((cloud) => {
      const title = cloud.querySelector('.swExplainCloud__copy strong');
      const subtitle = cloud.querySelector('.swExplainCloud__copy small');
      if (!title || !subtitle) return;
      if (!cloud.dataset.swDefaultTitle) {
        cloud.dataset.swDefaultTitle = title.textContent || 'Это как?';
        cloud.dataset.swDefaultSubtitle = subtitle.textContent || 'Что именно было сделано';
      }
      title.textContent = recall ? 'Что было сделано' : cloud.dataset.swDefaultTitle;
      subtitle.textContent = recall ? 'Покажем каждый шаг обработки и его пользу' : cloud.dataset.swDefaultSubtitle;
    });
  };
  sync();
  new MutationObserver(sync).observe(document.documentElement, {attributes:true, attributeFilter:['class']});
})();
</script>
