  .swResultCarousel37__arrow{position:absolute;z-index:8;top:calc(50% - 30px);width:70px;height:106px;display:block;padding:0;border:0;border-radius:0;background:linear-gradient(145deg,rgba(14,126,78,.72),rgba(43,193,126,.58) 56%,rgba(177,255,218,.5));-webkit-backdrop-filter:blur(14px) saturate(1.35);backdrop-filter:blur(14px) saturate(1.35);cursor:pointer;opacity:.94;clip-path:polygon(0 0,100% 50%,0 100%);filter:drop-shadow(0 12px 14px rgba(4,74,44,.24)) drop-shadow(0 0 18px rgba(40,210,132,.22));transform:translateY(-50%);transition:transform .2s cubic-bezier(.2,.8,.2,1),filter .2s ease,opacity .2s ease,background .2s ease}
  .swResultCarousel37__arrow[data-sw-result-carousel-prev]{left:28px;clip-path:polygon(100% 0,0 50%,100% 100%)}
