  @keyframes swResultCarousel37Out{from{opacity:1;transform:translateX(0) skewX(0);filter:blur(0) contrast(1);text-shadow:0 0 transparent}to{opacity:.05;transform:translateX(-42px) skewX(-3deg);filter:blur(11px) contrast(1.8) saturate(.72);text-shadow:14px 0 rgba(0,255,155,.42),28px 0 rgba(0,178,255,.22)}}
  @keyframes swResultCarousel37OutPrev{from{opacity:1;transform:translateX(0) skewX(0);filter:blur(0) contrast(1);text-shadow:0 0 transparent}to{opacity:.05;transform:translateX(42px) skewX(3deg);filter:blur(11px) contrast(1.8) saturate(.72);text-shadow:-14px 0 rgba(0,255,155,.42),-28px 0 rgba(0,178,255,.22)}}
  @keyframes swResultCarousel37In{0%{opacity:.04;transform:translateX(54px) skewX(-4deg) scale(.99);filter:blur(14px) contrast(2) saturate(.7);text-shadow:-18px 0 rgba(0,255,155,.5),-36px 0 rgba(0,178,255,.26)}58%{opacity:.82;filter:blur(2px) contrast(1.16);text-shadow:-5px 0 rgba(0,255,155,.18)}100%{opacity:1;transform:translateX(0) skewX(0) scale(1);filter:blur(0) contrast(1) saturate(1);text-shadow:0 0 transparent}}
  @keyframes swResultCarousel37InPrev{0%{opacity:.04;transform:translateX(-54px) skewX(4deg) scale(.99);filter:blur(14px) contrast(2) saturate(.7);text-shadow:18px 0 rgba(0,255,155,.5),36px 0 rgba(0,178,255,.26)}58%{opacity:.82;filter:blur(2px) contrast(1.16);text-shadow:5px 0 rgba(0,255,155,.18)}100%{opacity:1;transform:translateX(0) skewX(0) scale(1);filter:blur(0) contrast(1) saturate(1);text-shadow:0 0 transparent}}
  @keyframes swResultCarousel37NextCue{0%,100%{opacity:.94;transform:translateY(-50%) translateX(0) scale(1)}38%{opacity:1;transform:translateY(-50%) translateX(9px) scale(1.11);filter:brightness(1.14) saturate(1.16) drop-shadow(0 0 32px rgba(35,214,132,.6))}70%{transform:translateY(-50%) translateX(-2px) scale(1.02)}}
