<script id="codex-index-mobile-listener-copy-v1">
(() => {
  'use strict';
  if (window.__swIndexMobileListenerCopyV1) return;
  window.__swIndexMobileListenerCopyV1 = true;

  const active = () => {
    const state = String(document.body?.dataset?.pageState || '');
    return window.innerWidth <= 1023 && (document.documentElement.classList.contains('upload-active') || document.documentElement.classList.contains('sw-processing-final-active') || /^(uploading|processing|queued|paid-processing)$/i.test(state));
  };
  const benefitFor = (value) => {
    const s = String(value || '').toLowerCase();
    if (/mp3|сжат|зернист|металл/.test(s)) return 'Металлическая зернистость и размазанные атаки станут тише — слушатель услышит чище верх и естественнее детали.';
    if (/шум|гул|шип|хвост/.test(s)) return 'Слушатель услышит чище паузы и тихие места: лишний фон, гул и шипение не будут отвлекать.';
    if (/пик|перегруз|клип|транзиент/.test(s)) return 'Слушатель услышит меньше хруста и резких ударов на пиках, а атака инструментов останется живой.';
    if (/громк|loud|headroom|динами/.test(s)) return 'Громкость станет увереннее и ровнее, без ощущения зажатого трека и без потери движения.';
    if (/баланс|частот|спектр|низ|бас|середин|верх/.test(s)) return 'Бас, середина и верх зазвучат собранно: трек станет плотнее, чище и легче читается на разных системах.';
    if (/детал|воздух|панорам|атака/.test(s)) return 'Слушатель услышит больше воздуха, атаки и мелких музыкальных деталей без резкости.';
    if (/перевод|телефон|науш|систем/.test(s)) return 'Собранный баланс сохранится в телефоне, наушниках, автомобиле и студийных мониторах.';
    if (/готов|выдач|финал|master|рендер/.test(s)) return 'На выходе слушатель получит цельный чистый мастер с сохранённой динамикой и без случайных артефактов.';
    return 'Слушатель услышит более чистый, ровный и собранный трек с сохранённой живой динамикой.';
  };
  const sync = () => {
    if (!active()) return;
    document.querySelectorAll('#swFastStatus,.swFastStatus').forEach((legacy) => {
      legacy.style.setProperty('display', 'none', 'important');
      legacy.style.setProperty('visibility', 'hidden', 'important');
      legacy.style.setProperty('opacity', '0', 'important');
      legacy.style.setProperty('pointer-events', 'none', 'important');
    });
    const rail = document.getElementById('swProcessingStatusRail');
    if (!rail) return;
    const title = rail.querySelector('.swProcessingStatusTitle');
    const text = rail.querySelector('.swProcessingStatusText');
    const orb = document.getElementById('swFastProcessOrb');
    const sourceTitle = orb?.querySelector('.swFinalOrbCopy__title')?.textContent || document.getElementById('swFastStatusTitle')?.textContent || '';
    const sourceText = orb?.querySelector('.swFinalOrbCopy__text')?.textContent || document.getElementById('swFastStatusText')?.textContent || '';
    const stage = window.__swProcessingStage37 || null;
    const stageLabel = rail.querySelector('[data-sw-processing-stage]');
    if (stageLabel) {
      const stageNumber = Math.max(1, Number(stage?.index) + 1 || 1);
      const stageTotal = Math.max(1, Number(stage?.total) || 37);
      stageLabel.textContent = `Этап ${stageNumber} из ${stageTotal}`;
    }
    const state = String(document.body?.dataset?.pageState || '').toLowerCase();
    const isFileIntake = state === 'uploading' && (!stage || Number(stage.percent || 0) <= 1);
    if (isFileIntake) {
      if (title) title.textContent = 'Приемка файла';
      if (text) text.textContent = 'Идет приемка файла и рендеринг графической волны.';
      return;
    }
    if (title && sourceTitle) title.textContent = sourceTitle;
    if (text && sourceText) text.textContent = sourceText;
  };
  sync();
  new MutationObserver(sync).observe(document.documentElement, {attributes:true, attributeFilter:['class']});
  if (document.body) new MutationObserver(sync).observe(document.body, {attributes:true, attributeFilter:['data-page-state']});
  window.addEventListener('resize', sync, {passive:true});
  window.setInterval(sync, 900);
})();
</script>
