<script id="codex-result-recall-wave-centered-v2-js">
(() => {
  'use strict';
  if (window.__swResultRecallWaveCenteredV2) return;
  window.__swResultRecallWaveCenteredV2 = true;
  const root = document.documentElement;
  const active = () => root.classList.contains('sw-has-result-recall') && !root.classList.contains('upload-active');
  const alignNamesAboveWaves = () => {
    document.querySelectorAll('.swResultRecall__button').forEach((button) => {
      const name = button.querySelector('.swResultRecall__name');
      const wave = button.querySelector('.swResultRecall__wave');
      if (!name || !wave) return;
      name.style.setProperty('--sw-recall-name-lift', '0px');
      const nameRect = name.getBoundingClientRect();
      const waveRect = wave.getBoundingClientRect();
      if (nameRect.height < 1 || waveRect.height < 1) return;
      /* Keep a filename-high clear band between its baseline and the waveform. */
      const lift = Math.max(0, nameRect.bottom - waveRect.top + nameRect.height);
      name.style.setProperty('--sw-recall-name-lift', `${lift.toFixed(2)}px`);
    });
  };
  const sync = () => {
    if (!active()) return;
    document.querySelectorAll('.swExplainCloud').forEach((cloud) => {
      cloud.style.setProperty('display','none','important');
      cloud.style.setProperty('visibility','hidden','important');
      cloud.style.setProperty('pointer-events','none','important');
    });
    alignNamesAboveWaves();
    if (!window.matchMedia('(min-width:1024px)').matches) return;
    const cards = document.querySelector('.swIndexProofMetrics');
    const copy = document.querySelector('.swFastDesktopCopy');
    if (!cards || !copy) return;
    const cardsRect = cards.getBoundingClientRect();
    const copyRect = copy.getBoundingClientRect();
    if (cardsRect.width < 1 || copyRect.width < 1) return;
    const targetWidth = Math.min(cardsRect.width, window.innerWidth - 24);
    const targetLeft = Math.max(12, cardsRect.left + (cardsRect.width - targetWidth) / 2);
    copy.style.setProperty('width', `${targetWidth.toFixed(2)}px`, 'important');
    copy.style.setProperty('left', `${targetLeft.toFixed(2)}px`, 'important');
    copy.dataset.swRecallCentered = '1';
  };
  sync();
  new MutationObserver(sync).observe(root, {attributes:true,attributeFilter:['class']});
  window.addEventListener('resize', sync, {passive:true});
  document.addEventListener('load', sync, true);
  window.setInterval(sync, 500);
})();
</script>
