  const drawing = '<path d="M8.3 23.7H6.9A4.9 4.9 0 0 1 2 18.8a5 5 0 0 1 4.8-5A9.3 9.3 0 0 1 16 5.7c3.8 0 7.1 2.3 8.5 5.6a6.2 6.2 0 0 1 4.4 1.8 6 6 0 0 1 1.8 4.3 6.3 6.3 0 0 1-6.4 6.3h-3.7"></path><path class="swUploadOrbCloudGear__arrow" d="M14.4 27V16.2m-4 4 4-4 4 4"></path><g class="swUploadOrbCloudGear__gear"><circle cx="25.3" cy="9.1" r="5.1"></circle><circle cx="25.3" cy="9.1" r="2"></circle><path d="M25.3 1.8v2.1m0 10.4v2.1M18 9.1h2.1m10.4 0h2.1M20.1 3.9l1.5 1.5m7.4 7.4 1.5 1.5m0-10.4L29 5.4m-7.4 7.4-1.5 1.5"></path></g>';
  const addIcon = (orb) => {
    if (!(orb instanceof HTMLElement) || orb.querySelector(':scope > .swUploadOrbCloudGear')) return;
    const icon = document.createElement('i');
    icon.className = 'swUploadOrbCloudGear';
    icon.setAttribute('aria-hidden', 'true');
    icon.innerHTML = '<svg class="swUploadOrbCloudGear__trail" viewBox="0 0 36 30">' + drawing + '</svg><svg class="swUploadOrbCloudGear__main" viewBox="0 0 36 30">' + drawing + '</svg>';
    orb.appendChild(icon);
  };
  const sync = () => document.querySelectorAll('.swFastProcessOrb').forEach(addIcon);
  let touchTimer = 0;
  document.addEventListener('pointerdown', (event) => {
    const orb = event.target instanceof Element ? event.target.closest('.swFastProcessOrb') : null;
    if (!orb || event.pointerType === 'mouse') return;
    orb.classList.add('is-orb-icon-touching');
    window.clearTimeout(touchTimer);
    touchTimer = window.setTimeout(() => orb.classList.remove('is-orb-icon-touching'), 720);
  }, {passive:true});
  sync();
  new MutationObserver(sync).observe(document.documentElement, {childList:true,subtree:true});
})();
</script>
