<script id="codex-index-processing-copy-split-v1-js">
(() => {
  'use strict';
  if (window.__swIndexProcessingCopySplitV1) return;
  window.__swIndexProcessingCopySplitV1 = true;

  const split = () => {
    const panel = document.querySelector('#swProcessingStatusRail .swProcessingStatusPanel');
    if (!panel || panel.dataset.swCopySplit === '1') return;
    const wait = panel.querySelector(':scope > .swProcessingStatusWait');
    const title = panel.querySelector(':scope > .swProcessingStatusTitle');
    const stage = panel.querySelector(':scope > [data-sw-processing-stage]');
    const text = panel.querySelector(':scope > .swProcessingStatusText');
    const steps = panel.querySelector(':scope > .swProcessingStatusSteps');
    if (!wait || !title || !text || !steps) return;

    const headline = document.createElement('div');
    headline.className = 'swProcessingStatusHeadline';
    const detail = document.createElement('div');
    detail.className = 'swProcessingStatusDetail';
    panel.insertBefore(headline, wait);
    panel.insertBefore(detail, text);
    headline.append(wait, title);
    if (stage) detail.append(stage);
    detail.append(text, steps);
    panel.dataset.swCopySplit = '1';
  };

  split();
  new MutationObserver(split).observe(document.documentElement, {childList:true,subtree:true});
})();
</script>
