  html body #resultModal .swResultGrowthArrow{display:grid!important;place-items:center!important;width:clamp(30px,2.8vw,44px)!important;height:clamp(22px,2.35vw,36px)!important;opacity:0;visibility:hidden;transform:translate3d(0,13px,0) scaleY(.55);transform-origin:50% 100%;filter:drop-shadow(0 0 0 rgba(255,175,29,0));pointer-events:none!important}
  html body #resultModal .swResultGrowthArrow svg{display:block!important;width:100%!important;height:100%!important;overflow:visible!important}
  html body #resultModal .swResultGrowthArrow path{fill:none!important;stroke-linecap:round!important;stroke-linejoin:round!important;vector-effect:non-scaling-stroke!important;stroke-dashoffset:100}
  html body #resultModal .swResultGrowthArrow__outer{stroke:#ff9f1c!important;stroke-width:9!important;stroke-dasharray:100!important}
  html body #resultModal .swResultGrowthArrow__inner{stroke:#ffe06a!important;stroke-width:7!important;stroke-dasharray:70!important}
  html body #resultModal #impactGrowthTrigger.has-sw-growth-arrow .swResultGrowthArrow{opacity:1;visibility:visible;animation:swResultGrowthArrowRevealV1 .82s cubic-bezier(.2,.78,.22,1) both}
  html body #resultModal #impactGrowthTrigger.has-sw-growth-arrow .swResultGrowthArrow__outer{animation:swResultGrowthArrowDrawV1 .72s cubic-bezier(.22,.7,.2,1) .06s both}
  html body #resultModal #impactGrowthTrigger.has-sw-growth-arrow .swResultGrowthArrow__inner{animation:swResultGrowthArrowDrawV1 .54s cubic-bezier(.22,.7,.2,1) .16s both}
  @keyframes swResultGrowthArrowRevealV1{0%{opacity:0;transform:translate3d(0,13px,0) scaleY(.55);filter:drop-shadow(0 0 0 rgba(255,175,29,0))}62%{opacity:1;transform:translate3d(0,-2px,0) scaleY(1.04);filter:drop-shadow(0 0 13px rgba(255,175,29,.72))}100%{opacity:1;transform:translate3d(0,0,0) scaleY(1);filter:drop-shadow(0 0 7px rgba(255,175,29,.42))}}
  @keyframes swResultGrowthArrowDrawV1{from{stroke-dashoffset:100}to{stroke-dashoffset:0}}
  @media(max-width:600px){html body #resultModal #impactGrowthTrigger{row-gap:3px!important;padding:8px 6px!important}html body #resultModal .swResultGrowthArrow{width:30px!important;height:22px!important}}
