<script id="codex-processing-progress-smooth-v1-js">
(() => {
  'use strict';
  if (window.__codexProcessingProgressSmoothV1) return;
  window.__codexProcessingProgressSmoothV1 = true;
  const root = document.documentElement;
  let shown = 0;
  let raw = 0;
  let previousRaw = 0;
  let above55At = 0;
  let last = 0;
  let wasActive = false;
  const active = () => {
    const state = String(document.body?.dataset?.pageState || '').toLowerCase();
    return root.classList.contains('upload-active')
      || root.classList.contains('sw-processing-final-active')
      || /^(uploading|processing|queued|paid-processing)$/.test(state);
  };
  const number = (value) => {
    const n = Number(value);
    return Number.isFinite(n) ? Math.max(0, Math.min(100, n)) : 0;
  };
  const read = () => {
    let value = 0;
    document.querySelectorAll('#swFastStatusBar,#swFastProcessOrb,[aria-valuenow]').forEach((element) => {
      const style = element.getAttribute('style') || '';
      const css = /--sw-process-pct\s*:\s*([0-9.]+)/i.exec(style);
      const width = /width\s*:\s*([0-9.]+)%/i.exec(style);
      const aria = element.getAttribute('aria-valuenow');
      value = Math.max(value, number(css?.[1] || width?.[1] || aria || 0));
    });
    document.querySelectorAll('#swFastStatusText,#swProcessingStatusText').forEach((element) => {
      const match = /([0-9]{1,3}(?:[.,][0-9]+)?)\s*%/.exec(element.textContent || '');
      if (match) value = Math.max(value, number(match[1].replace(',', '.')));
    });
    return value;
  };
  const write = (value) => {
    const pct = Math.max(0, Math.min(100, value));
    root.style.setProperty('--sw-process-pct', pct.toFixed(2));
    document.querySelectorAll('#swFastStatusBar').forEach((element) => element.style.setProperty('width', pct.toFixed(2) + '%'));
    document.querySelectorAll('#swFastStatusText,#swProcessingStatusText').forEach((element) => {
      if (!element.dataset.codexSmoothText) element.dataset.codexSmoothText = element.textContent || '';
      const source = element.dataset.codexSmoothText;
      if (/([0-9]{1,3}(?:[.,][0-9]+)?)\s*%/.test(source)) {
        element.textContent = source.replace(/([0-9]{1,3}(?:[.,][0-9]+)?)\s*%/, Math.round(pct) + '%');
      }
    });
  };
  const tick = (now) => {
    const live = active();
    if (!live) {
      if (wasActive) { shown = 0; raw = 0; previousRaw = 0; above55At = 0; }
      wasActive = false;
      last = now;
      return;
    }
    wasActive = true;
    const delta = last ? Math.min(1.2, Math.max(.08, (now - last) * .0016)) : 0;
    last = now;
    raw = Math.max(raw, read());
    if (raw + 8 < previousRaw && raw < 20) shown = raw;
    previousRaw = raw;
    if (raw >= 55 && !above55At) above55At = Date.now();
    const synthetic = above55At ? Math.min(96, 55 + (Date.now() - above55At) * .22 / 1000) : raw;
    const target = raw >= 100 ? 100 : (raw >= 55 ? Math.min(96, Math.max(raw, synthetic)) : Math.min(55, raw));
    if (target > shown) shown = Math.min(target, shown + Math.max(delta, .08));
    write(shown);
  };
  window.setInterval(() => tick(performance.now()), 250);
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => tick(performance.now()), {once:true});
  else tick(performance.now());
})();
</script>
</body>
</html>
